    let financialOverviewCache = { fetchedAt: 0, rows: [], pageCount: 0, lastPage: 0, coverageStartMs: null, coverageEndMs: null, complete: false, malformedRowCount: 0, duplicateDateCount: 0 };

    function financeNormaliseText(value) {
        return String(value || '').normalize('NFKC').replace(/\s+/gu, ' ').trim();
    }

    function financeHashString(value) {
        const text = String(value || '');
        let first = 0x811c9dc5;
        let second = 0x9e3779b9;
        for (let index = 0; index < text.length; index++) {
            const code = text.charCodeAt(index);
            first ^= code;
            first = Math.imul(first, 0x01000193) >>> 0;
            second ^= code + index;
            second = Math.imul(second, 0x85ebca6b) >>> 0;
        }
        return `${first.toString(36).padStart(7, '0')}${second.toString(36).padStart(7, '0')}`;
    }

    function compileFinancialRule(rule) {
        const compiled = { ...rule };
        compiled.patternRegex = null;
        compiled.excludeRegex = null;
        if (compiled.match === 'regex') {
            try { compiled.patternRegex = new RegExp(compiled.pattern, 'iu'); } catch (err) {}
        }
        if (compiled.excludePattern) {
            try { compiled.excludeRegex = new RegExp(compiled.excludePattern, 'iu'); } catch (err) {}
        }
        return compiled;
    }

    function financeRandomToken(byteLength = 24) {
        const bytes = new Uint8Array(Math.max(16, Number(byteLength) || 24));
        const cryptoObject = pageWindow.crypto || globalThis.crypto;
        if (cryptoObject?.getRandomValues) cryptoObject.getRandomValues(bytes);
        else for (let index = 0; index < bytes.length; index++) bytes[index] = Math.floor(Math.random() * 256);
        let binary = '';
        for (const byte of bytes) binary += String.fromCharCode(byte);
        return btoa(binary).replace(/\+/gu, '-').replace(/\//gu, '_').replace(/=+$/gu, '');
    }

    function financePlayerIdentity(account = null) {
        const id = account?.userId ?? currentUserIdCached();
        const name = financeNormaliseText(account?.userName || document.querySelector?.('#navbar_profile_link, a[href*="/profile/"]')?.textContent || '');
        return { id: id === undefined || id === null || id === '' ? null : String(id), name: name.slice(0, 120) };
    }

    function financePlayerProfileKey(player) {
        if (player?.id) return `id:${String(player.id)}`;
        return `name:${financeHashString(String(player?.name || 'unknown').toLowerCase())}`;
    }

    function financeVaultCredential() {
        const fallback = { deviceId: financeRandomToken(16), playerId: null, playerName: '', createdAt: Date.now() };
        const raw = gmGetValueSafe(SCRIPT.financeVaultCredentialState, '');
        let identity = null;
        try { identity = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (err) {}
        if (!identity || typeof identity !== 'object') identity = fallback;
        identity.deviceId = String(identity.deviceId || fallback.deviceId).slice(0, 80);
        identity.playerId = identity.playerId === undefined || identity.playerId === null || identity.playerId === '' ? null : String(identity.playerId).slice(0, 64);
        identity.playerName = financeNormaliseText(identity.playerName).slice(0, 120);
        identity.createdAt = Number(identity.createdAt) || Date.now();
        delete identity.syncKey;
        if (!raw || String(raw).includes('syncKey')) saveFinanceVaultCredential(identity);
        return identity;
    }

    function saveFinanceVaultCredential(identity) {
        const safe = {
            deviceId: String(identity?.deviceId || financeRandomToken(16)).slice(0, 80),
            playerId: identity?.playerId === undefined || identity?.playerId === null || identity?.playerId === '' ? null : String(identity.playerId).slice(0, 64),
            playerName: financeNormaliseText(identity?.playerName).slice(0, 120),
            createdAt: Number(identity?.createdAt) || Date.now()
        };
        return gmSetValueSafe(SCRIPT.financeVaultCredentialState, JSON.stringify(safe));
    }

    function ensureFinanceVaultCredential(player = null) {
        const identity = financeVaultCredential();
        const current = player || financePlayerIdentity();
        if (current?.id) identity.playerId = String(current.id);
        if (current?.name) identity.playerName = current.name;
        if (!identity.deviceId) identity.deviceId = financeRandomToken(16);
        saveFinanceVaultCredential(identity);
        return identity;
    }

    function invalidateFinanceVaultMemory() {
        financeVaultStoreMemory = null;
        financeVaultProfileMemory.clear();
    }

    function loadFinanceVaultStore() {
        if (financeVaultStoreMemory) return financeVaultStoreMemory;
        const raw = gmGetValueSafe(SCRIPT.financeVaultState, '');
        let store = null;
        try { store = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (err) {}
        if (!store || typeof store !== 'object' || !store.profiles || typeof store.profiles !== 'object') {
            store = { schema: FINANCE_VAULT_SCHEMA, profiles: {} };
        }
        store.schema = FINANCE_VAULT_SCHEMA;
        financeVaultStoreMemory = store;
        return store;
    }

    function saveFinanceVaultStore(store, { preserveProfileCache = false } = {}) {
        financeVaultStoreMemory = store;
        if (!preserveProfileCache) financeVaultProfileMemory.clear();
        return gmSetValueSafe(SCRIPT.financeVaultState, JSON.stringify(store));
    }

    function defaultFinanceVault(player, deviceId) {
        return {
            schema: FINANCE_VAULT_SCHEMA,
            player: { id: player?.id || null, name: financeNormaliseText(player?.name).slice(0, 120) },
            deviceId: String(deviceId || '').slice(0, 80),
            syncRevision: 0,
            coverageStartMs: null,
            coverageEndMs: null,
            lastFullScanAt: 0,
            lastIncrementalScanAt: 0,
            lastDeepScanAt: 0,
            sourceLastPage: 0,
            deepScanCursorPage: 0,
            deepScanTotalPages: 0,
            deepScanAnchor: '',
            deepScanInProgress: false,
            archiveComplete: false,
            archiveTruncated: false,
            droppedTransactions: 0,
            updatedAt: Date.now(),
            balanceCheckpoints: [],
            transactions: []
        };
    }

    function normaliseFinanceVaultEntry(entry) {
        const timestamp = Number(entry?.timestamp);
        const amount = Math.round(Number(entry?.amount) || 0);
        const description = financeNormaliseText(entry?.description).slice(0, 500);
        if (!Number.isFinite(timestamp) || !amount || !description) return null;
        const dateLabel = financeNormaliseText(entry?.dateLabel).slice(0, 120);
        const rawTimestamp = financeNormaliseText(entry?.rawTimestamp).slice(0, 80);
        const sourceKey = String(entry?.sourceKey || `${timestamp}|${amount}|${description.toLowerCase()}|${rawTimestamp || dateLabel}`).slice(0, 700);
        const occurrence = Math.max(1, Math.round(Number(entry?.occurrence) || 1));
        const fingerprint = String(entry?.fingerprint || `${timestamp.toString(36)}-${financeHashString(sourceKey)}-${occurrence.toString(36)}`).slice(0, 120);
        return { fingerprint, sourceKey, occurrence, timestamp, amount, description, dateLabel, rawTimestamp };
    }

    function normaliseFinanceVault(vault, player, deviceId) {
        const next = vault && typeof vault === 'object' ? { ...vault } : defaultFinanceVault(player, deviceId);
        next.schema = FINANCE_VAULT_SCHEMA;
        next.player = { id: player?.id || next.player?.id || null, name: financeNormaliseText(player?.name || next.player?.name).slice(0, 120) };
        next.deviceId = String(deviceId || next.deviceId || '').slice(0, 80);
        next.syncRevision = Math.max(0, Math.round(Number(next.syncRevision) || 0));
        next.coverageStartMs = Number.isFinite(Number(next.coverageStartMs)) ? Number(next.coverageStartMs) : null;
        next.coverageEndMs = Number.isFinite(Number(next.coverageEndMs)) ? Number(next.coverageEndMs) : null;
        next.lastFullScanAt = Number(next.lastFullScanAt) || 0;
        next.lastIncrementalScanAt = Number(next.lastIncrementalScanAt) || 0;
        next.lastDeepScanAt = Number(next.lastDeepScanAt) || 0;
        next.sourceLastPage = Math.max(0, Math.round(Number(next.sourceLastPage) || 0));
        next.deepScanCursorPage = Math.max(0, Math.round(Number(next.deepScanCursorPage) || 0));
        next.deepScanTotalPages = Math.max(0, Math.round(Number(next.deepScanTotalPages) || 0));
        next.deepScanAnchor = String(next.deepScanAnchor || '').slice(0, 1200);
        next.deepScanInProgress = Boolean(next.deepScanInProgress);
        next.archiveComplete = Boolean(next.archiveComplete);
        next.archiveTruncated = Boolean(next.archiveTruncated);
        if (next.archiveComplete) next.deepScanInProgress = false;
        next.droppedTransactions = Math.max(0, Math.round(Number(next.droppedTransactions) || 0));
        next.updatedAt = Number(next.updatedAt) || Date.now();
        next.balanceCheckpoints = Array.isArray(next.balanceCheckpoints) ? next.balanceCheckpoints.map(item => ({ timestamp: Number(item?.timestamp), balance: Math.round(Number(item?.balance) || 0) })).filter(item => Number.isFinite(item.timestamp) && Number.isFinite(item.balance)).slice(-FINANCE_VAULT_MAX_CHECKPOINTS) : [];
        const seen = new Set();
        next.transactions = Array.isArray(next.transactions) ? next.transactions.map(normaliseFinanceVaultEntry).filter(entry => entry && !seen.has(entry.fingerprint) && seen.add(entry.fingerprint)).sort((a, b) => a.timestamp - b.timestamp || a.fingerprint.localeCompare(b.fingerprint)) : [];
        if (next.transactions.length > FINANCE_VAULT_MAX_TRANSACTIONS) {
            const dropped = next.transactions.length - FINANCE_VAULT_MAX_TRANSACTIONS;
            next.transactions = next.transactions.slice(-FINANCE_VAULT_MAX_TRANSACTIONS);
            next.droppedTransactions += dropped;
            next.archiveTruncated = true;
            next.archiveComplete = false;
            next.deepScanInProgress = false;
            next.coverageStartMs = next.transactions[0]?.timestamp || next.coverageStartMs;
        }
        return next;
    }

    function loadFinanceVault(player, deviceId = financeVaultCredential().deviceId) {
        const key = financePlayerProfileKey(player);
        if (financeVaultProfileMemory.has(key)) return financeVaultProfileMemory.get(key);
        const store = loadFinanceVaultStore();
        const vault = normaliseFinanceVault(store.profiles[key], player, deviceId);
        store.profiles[key] = vault;
        financeVaultProfileMemory.set(key, vault);
        return vault;
    }

    function saveFinanceVault(vault) {
        const player = vault?.player || financePlayerIdentity();
        const identity = ensureFinanceVaultCredential(player);
        const normalised = normaliseFinanceVault(vault, player, identity.deviceId);
        normalised.updatedAt = Date.now();
        const retentionSetting = state.financialVault.retentionDays;
        if (String(retentionSetting) !== 'all') {
            const retentionMs = Math.max(1, Number(retentionSetting) || 365) * 86400000;
            const threshold = Date.now() - retentionMs;
            normalised.transactions = normalised.transactions.filter(entry => entry.timestamp >= threshold);
            normalised.balanceCheckpoints = normalised.balanceCheckpoints.filter(item => item.timestamp >= threshold);
            if (normalised.coverageStartMs !== null && normalised.coverageStartMs < threshold) normalised.coverageStartMs = threshold;
            normalised.archiveComplete = false;
        }
        if (normalised.transactions.length > FINANCE_VAULT_MAX_TRANSACTIONS) {
            const dropped = normalised.transactions.length - FINANCE_VAULT_MAX_TRANSACTIONS;
            normalised.transactions = normalised.transactions.slice(-FINANCE_VAULT_MAX_TRANSACTIONS);
            normalised.droppedTransactions += dropped;
            normalised.archiveTruncated = true;
            normalised.archiveComplete = false;
            normalised.coverageStartMs = normalised.transactions[0]?.timestamp || normalised.coverageStartMs;
        }
        normalised.balanceCheckpoints = normalised.balanceCheckpoints.slice(-FINANCE_VAULT_MAX_CHECKPOINTS);
        const store = loadFinanceVaultStore();
        const profileKey = financePlayerProfileKey(player);
        store.profiles[profileKey] = normalised;
        financeVaultProfileMemory.set(profileKey, normalised);
        saveFinanceVaultStore(store, { preserveProfileCache: true });
        return normalised;
    }

    function decorateFinancialEntries(entries) {
        const counts = new Map();
        return entries.slice().sort((a, b) => a.timestamp - b.timestamp || a.page - b.page || a.row - b.row).map(entry => {
            const timestamp = Number(entry.timestamp);
            const amount = Math.round(Number(entry.amount) || 0);
            const description = financeNormaliseText(entry.description);
            const dateLabel = financeNormaliseText(entry.dateLabel);
            const rawTimestamp = financeNormaliseText(entry.rawTimestamp);
            const sourceKey = String(entry?.sourceKey || `${timestamp}|${amount}|${description.toLowerCase()}|${rawTimestamp || dateLabel}`).slice(0, 700);
            const previous = counts.get(sourceKey) || 0;
            const suppliedOccurrence = Math.max(0, Math.round(Number(entry?.occurrence) || 0));
            const occurrence = suppliedOccurrence || previous + 1;
            counts.set(sourceKey, Math.max(previous, occurrence));
            return normaliseFinanceVaultEntry({ ...entry, sourceKey, occurrence, fingerprint: entry?.fingerprint || '' });
        }).filter(Boolean);
    }

    function mergeFinanceVaultEntries(vault, entries, { coverageStartMs = null, coverageEndMs = null, fullScan = false, deepScan = false, sourceLastPage = 0, deepScanCursorPage = null, deepScanTotalPages = null, deepScanAnchor = null, deepScanInProgress = null, archiveComplete = null, currentBalance = null } = {}) {
        const merged = new Map(vault.transactions.map(entry => [entry.fingerprint, entry]));
        for (const entry of decorateFinancialEntries(entries)) merged.set(entry.fingerprint, entry);
        vault.transactions = Array.from(merged.values()).sort((a, b) => a.timestamp - b.timestamp || a.fingerprint.localeCompare(b.fingerprint));
        if (Number.isFinite(Number(coverageStartMs))) vault.coverageStartMs = vault.coverageStartMs === null ? Number(coverageStartMs) : Math.min(vault.coverageStartMs, Number(coverageStartMs));
        if (Number.isFinite(Number(coverageEndMs))) vault.coverageEndMs = vault.coverageEndMs === null ? Number(coverageEndMs) : Math.max(vault.coverageEndMs, Number(coverageEndMs));
        if (fullScan) vault.lastFullScanAt = Date.now();
        else vault.lastIncrementalScanAt = Date.now();
        if (deepScan) vault.lastDeepScanAt = Date.now();
        if (Number(sourceLastPage) > 0) vault.sourceLastPage = Math.max(vault.sourceLastPage || 0, Math.round(Number(sourceLastPage)));
        if (deepScanCursorPage !== null) vault.deepScanCursorPage = Math.max(0, Math.round(Number(deepScanCursorPage) || 0));
        if (deepScanTotalPages !== null) vault.deepScanTotalPages = Math.max(0, Math.round(Number(deepScanTotalPages) || 0));
        if (deepScanAnchor !== null) vault.deepScanAnchor = String(deepScanAnchor || '').slice(0, 1200);
        if (deepScanInProgress !== null) vault.deepScanInProgress = Boolean(deepScanInProgress);
        if (archiveComplete !== null) vault.archiveComplete = Boolean(archiveComplete) && !vault.archiveTruncated;
        if (Number.isFinite(Number(currentBalance))) {
            const timestamp = Date.now();
            const last = vault.balanceCheckpoints[vault.balanceCheckpoints.length - 1];
            if (!last || Math.abs(timestamp - last.timestamp) > 5 * 60 * 1000 || last.balance !== Math.round(currentBalance)) {
                vault.balanceCheckpoints.push({ timestamp, balance: Math.round(currentBalance) });
            }
        }
        vault.syncRevision += 1;
        return saveFinanceVault(vault);
    }

    function financeFormatTimeAgo(timestamp) {
        const elapsed = Math.max(0, Date.now() - Number(timestamp || 0));
        if (elapsed < 60000) return 'just now';
        if (elapsed < 3600000) return `${Math.floor(elapsed / 60000)}m ago`;
        if (elapsed < 86400000) return `${Math.floor(elapsed / 3600000)}h ago`;
        return `${Math.floor(elapsed / 86400000)}d ago`;
    }

    function financeVaultStats(vault) {
        const transactions = Array.isArray(vault?.transactions) ? vault.transactions : [];
        return {
            count: transactions.length,
            firstTimestamp: transactions.length ? transactions[0].timestamp : null,
            lastTimestamp: transactions.length ? transactions[transactions.length - 1].timestamp : null,
            checkpoints: Array.isArray(vault?.balanceCheckpoints) ? vault.balanceCheckpoints.length : 0,
            lastDeepScanAt: Number(vault?.lastDeepScanAt) || 0,
            lastIncrementalScanAt: Number(vault?.lastIncrementalScanAt) || 0,
            sourceLastPage: Math.max(0, Math.round(Number(vault?.sourceLastPage) || 0)),
            deepScanCursorPage: Math.max(0, Math.round(Number(vault?.deepScanCursorPage) || 0)),
            deepScanTotalPages: Math.max(0, Math.round(Number(vault?.deepScanTotalPages) || 0)),
            deepScanInProgress: Boolean(vault?.deepScanInProgress),
            archiveComplete: Boolean(vault?.archiveComplete),
            archiveTruncated: Boolean(vault?.archiveTruncated),
            droppedTransactions: Math.max(0, Math.round(Number(vault?.droppedTransactions) || 0))
        };
    }

    function setFinanceVaultStatus(message, tone = 'neutral') {
        financeVaultStatus = String(message || '');
        financeVaultStatusTone = ['neutral', 'good', 'bad', 'busy'].includes(tone) ? tone : 'neutral';
        const status = document.querySelector(`#${SCRIPT.panelId} [data-finance-vault-status]`);
        if (status) {
            status.textContent = financeVaultStatus;
            status.dataset.tone = financeVaultStatusTone;
        }
    }

    function setFinanceRuleFeedStatus(message, tone = 'neutral') {
        financeRuleFeedStatus = String(message || '');
        financeRuleFeedStatusTone = ['neutral', 'good', 'bad', 'busy'].includes(tone) ? tone : 'neutral';
        const status = document.querySelector(`#${SCRIPT.panelId} [data-finance-rule-status]`);
        if (status) {
            status.textContent = financeRuleFeedStatus;
            status.dataset.tone = financeRuleFeedStatusTone;
        }
    }

    function financeExternalRequest({ method = 'GET', url, body = null, headers = {}, timeoutMs = FINANCE_FEED_TIMEOUT_MS }) {
        return new Promise((resolve, reject) => {
            if (runtime.destroyed) {
                reject(new Error('Toolkit runtime stopped.'));
                return;
            }
            if (typeof GM_xmlhttpRequest !== 'function') {
                reject(new Error('Tampermonkey cross-origin requests are unavailable.'));
                return;
            }
            let request = null;
            let settled = false;
            const finish = (error, response = null) => {
                if (settled) return;
                settled = true;
                if (request) runtime.requests.delete(request);
                if (error) reject(error); else resolve(response);
            };
            try {
                request = GM_xmlhttpRequest({
                    method,
                    url,
                    data: body,
                    headers,
                    timeout: timeoutMs,
                    responseType: 'text',
                    onload: response => finish(null, response),
                    onerror: () => finish(new Error('The GitHub financial-intelligence feed could not be reached.')),
                    ontimeout: () => finish(new Error('The GitHub financial-intelligence request timed out.')),
                    onabort: () => finish(new Error('The GitHub financial-intelligence request was cancelled.'))
                });
                if (!settled && request?.abort) runtime.requests.add(request);
            } catch (err) {
                finish(err instanceof Error ? err : new Error('The GitHub financial-intelligence request could not be created.'));
            }
        });
    }

    function validateFinancialRule(rawRule) {
        if (!rawRule || typeof rawRule !== 'object') return null;
        const direction = rawRule.direction === 'income' ? 'income' : rawRule.direction === 'spending' ? 'spending' : '';
        const match = ['regex', 'contains', 'startsWith', 'equals'].includes(rawRule.match) ? rawRule.match : '';
        const pattern = String(rawRule.pattern || '').slice(0, 180);
        const accountingGroup = FINANCE_ACCOUNTING_GROUPS.has(rawRule.accountingGroup) ? rawRule.accountingGroup : '';
        if (!direction || !match || !pattern || !accountingGroup) return null;
        if (match === 'regex') {
            try { new RegExp(pattern, 'iu'); } catch (err) { return null; }
        }
        const excludePattern = String(rawRule.excludePattern || '').slice(0, 180);
        if (excludePattern) {
            try { new RegExp(excludePattern, 'iu'); } catch (err) { return null; }
        }
        return compileFinancialRule({
            id: String(rawRule.id || financeHashString(`${direction}|${pattern}`)).slice(0, 80),
            direction,
            match,
            pattern,
            excludePattern,
            key: String(rawRule.key || 'unclassified').slice(0, 80),
            label: String(rawRule.label || 'Unclassified').slice(0, 120),
            accountingGroup,
            missionType: String(rawRule.missionType || '').slice(0, 40),
            confidence: clamp(rawRule.confidence, 0.05, 1, 0.5),
            source: 'remote'
        });
    }

    function applyFinancialRulePayload(payload, { cache = false } = {}) {
        if (!payload || Number(payload.schema) !== 1 || !Array.isArray(payload.rules)) return false;
        const rules = payload.rules.map(validateFinancialRule).filter(Boolean).slice(0, 250);
        if (!rules.length) return false;
        const fallbacks = { income: { ...BUILTIN_FINANCIAL_FALLBACKS.income }, spending: { ...BUILTIN_FINANCIAL_FALLBACKS.spending } };
        for (const direction of ['income', 'spending']) {
            const raw = payload.fallbacks?.[direction];
            if (!raw || typeof raw !== 'object') continue;
            const group = FINANCE_ACCOUNTING_GROUPS.has(raw.accountingGroup) ? raw.accountingGroup : fallbacks[direction].accountingGroup;
            fallbacks[direction] = {
                id: `remote-fallback-${direction}`,
                key: String(raw.key || fallbacks[direction].key).slice(0, 80),
                label: String(raw.label || fallbacks[direction].label).slice(0, 120),
                accountingGroup: group,
                missionType: String(raw.missionType || '').slice(0, 40),
                confidence: clamp(raw.confidence, 0.05, 1, fallbacks[direction].confidence)
            };
        }
        activeFinancialRules = rules;
        activeFinancialFallbacks = fallbacks;
        activeFinancialRuleVersion = String(payload.version || 'remote').slice(0, 80);
        if (cache) gmSetValueSafe(SCRIPT.financeRulesCacheState, JSON.stringify({ fetchedAt: Date.now(), payload }));
        return true;
    }

    function loadCachedFinancialRules() {
        const raw = gmGetValueSafe(SCRIPT.financeRulesCacheState, '');
        let cache = null;
        try { cache = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (err) {}
        if (!cache?.payload || !applyFinancialRulePayload(cache.payload)) return 0;
        return Number(cache.fetchedAt) || 0;
    }

    async function refreshFinancialRuleFeed(force = false) {
        if (!state.financialVault.ruleFeedEnabled) {
            activeFinancialRules = BUILTIN_FINANCIAL_RULES.map(rule => compileFinancialRule({ ...rule, source: 'built-in' }));
            activeFinancialFallbacks = { income: { ...BUILTIN_FINANCIAL_FALLBACKS.income }, spending: { ...BUILTIN_FINANCIAL_FALLBACKS.spending } };
            activeFinancialRuleVersion = 'built-in';
            setFinanceRuleFeedStatus('Built-in classification rules active.', 'neutral');
            return false;
        }
        if (financeRuleRefreshPromise) return financeRuleRefreshPromise;
        financeRuleRefreshPromise = (async () => {
            const cachedAt = loadCachedFinancialRules();
            if (!force && cachedAt && Date.now() - cachedAt < FINANCE_RULE_CACHE_TTL_MS) {
                setFinanceRuleFeedStatus(`Classification feed ${activeFinancialRuleVersion} · cached`, 'good');
                return true;
            }
            setFinanceRuleFeedStatus('Checking the central classification rule feed…', 'busy');
            try {
                const response = await financeExternalRequest({ url: `${FINANCE_RULE_FEED_URL}?v=${Date.now()}` });
                if (response.status < 200 || response.status >= 300) throw new Error(`Rule feed returned HTTP ${response.status}.`);
                const payload = JSON.parse(response.responseText || '{}');
                if (!applyFinancialRulePayload(payload, { cache: true })) throw new Error('Rule feed failed schema validation.');
                setFinanceRuleFeedStatus(`Classification feed ${activeFinancialRuleVersion} active.`, 'good');
                return true;
            } catch (err) {
                const cached = loadCachedFinancialRules();
                if (!cached) {
                    activeFinancialRules = BUILTIN_FINANCIAL_RULES.map(rule => compileFinancialRule({ ...rule, source: 'built-in' }));
                    activeFinancialRuleVersion = 'built-in';
                }
                setFinanceRuleFeedStatus(`${err?.message || 'Rule feed unavailable'} Using ${activeFinancialRuleVersion}.`, cached ? 'neutral' : 'bad');
                return false;
            }
        })().finally(() => { financeRuleRefreshPromise = null; });
        return financeRuleRefreshPromise;
    }

    function validateFinancialPolicy(payload) {
        if (!payload || Number(payload.schema) !== 2 || typeof payload.risk !== 'object' || typeof payload.scan !== 'object') return null;
        const number = (value, minimum, maximum, fallback) => clamp(Number(value), minimum, maximum, fallback);
        return {
            schema: 2,
            version: String(payload.version || 'remote').slice(0, 80),
            risk: {
                classificationCritical: number(payload.risk.classificationCritical, 40, 95, BUILTIN_FINANCIAL_POLICY.risk.classificationCritical),
                classificationWarning: number(payload.risk.classificationWarning, 50, 100, BUILTIN_FINANCIAL_POLICY.risk.classificationWarning),
                capitalIncomeRatio: number(payload.risk.capitalIncomeRatio, 50, 500, BUILTIN_FINANCIAL_POLICY.risk.capitalIncomeRatio),
                allianceConcentration: number(payload.risk.allianceConcentration, 40, 100, BUILTIN_FINANCIAL_POLICY.risk.allianceConcentration),
                categoryConcentration: number(payload.risk.categoryConcentration, 40, 100, BUILTIN_FINANCIAL_POLICY.risk.categoryConcentration),
                volatilityWarning: number(payload.risk.volatilityWarning, 50, 500, BUILTIN_FINANCIAL_POLICY.risk.volatilityWarning),
                revenueContraction: number(payload.risk.revenueContraction, -90, -5, BUILTIN_FINANCIAL_POLICY.risk.revenueContraction),
                drawdownWarning: number(payload.risk.drawdownWarning, 5, 90, BUILTIN_FINANCIAL_POLICY.risk.drawdownWarning),
                runwayCriticalDays: number(payload.risk.runwayCriticalDays, 0.5, 30, BUILTIN_FINANCIAL_POLICY.risk.runwayCriticalDays)
            },
            scan: {
                pageCap: Math.round(number(payload.scan.pageCap, 100, FINANCE_DEEP_SCAN_HARD_PAGE_CAP, BUILTIN_FINANCIAL_POLICY.scan.pageCap)),
                batchSize: Math.round(number(payload.scan.batchSize, 1, FINANCE_DEEP_SCAN_HARD_BATCH_CAP, BUILTIN_FINANCIAL_POLICY.scan.batchSize)),
                retryAttempts: Math.round(number(payload.scan.retryAttempts, 1, 5, BUILTIN_FINANCIAL_POLICY.scan.retryAttempts)),
                checkpointPages: Math.round(number(payload.scan.checkpointPages, 20, 500, BUILTIN_FINANCIAL_POLICY.scan.checkpointPages))
            }
        };
    }

    function applyFinancialPolicyPayload(payload, { cache = false } = {}) {
        const policy = validateFinancialPolicy(payload);
        if (!policy) return false;
        activeFinancialPolicy = policy;
        activeFinancialPolicyVersion = policy.version;
        if (cache) gmSetValueSafe(SCRIPT.financePolicyCacheState, JSON.stringify({ fetchedAt: Date.now(), payload }));
        return true;
    }

    function loadCachedFinancialPolicy() {
        const raw = gmGetValueSafe(SCRIPT.financePolicyCacheState, '');
        let cache = null;
        try { cache = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (err) {}
        if (!cache?.payload || !applyFinancialPolicyPayload(cache.payload)) return 0;
        return Number(cache.fetchedAt) || 0;
    }

    async function refreshFinancialPolicyFeed(force = false) {
        if (!state.financialVault.ruleFeedEnabled) {
            activeFinancialPolicy = clonePlainData(BUILTIN_FINANCIAL_POLICY);
            activeFinancialPolicyVersion = 'built-in';
            return false;
        }
        if (financePolicyRefreshPromise) return financePolicyRefreshPromise;
        financePolicyRefreshPromise = (async () => {
            const cachedAt = loadCachedFinancialPolicy();
            if (!force && cachedAt && Date.now() - cachedAt < FINANCE_POLICY_CACHE_TTL_MS) return true;
            try {
                const response = await financeExternalRequest({ url: `${FINANCE_POLICY_FEED_URL}?v=${Date.now()}` });
                if (response.status < 200 || response.status >= 300) throw new Error(`Audit policy returned HTTP ${response.status}.`);
                const payload = JSON.parse(response.responseText || '{}');
                if (!applyFinancialPolicyPayload(payload, { cache: true })) throw new Error('Audit policy failed schema validation.');
                return true;
            } catch (err) {
                const cached = loadCachedFinancialPolicy();
                if (!cached) {
                    activeFinancialPolicy = clonePlainData(BUILTIN_FINANCIAL_POLICY);
                    activeFinancialPolicyVersion = 'built-in';
                }
                return false;
            }
        })().finally(() => { financePolicyRefreshPromise = null; });
        return financePolicyRefreshPromise;
    }

    async function refreshFinancialIntelligenceFeeds(force = false) {
        if (!state.financialVault.ruleFeedEnabled) {
            await Promise.all([refreshFinancialRuleFeed(force), refreshFinancialPolicyFeed(force)]);
            setFinanceRuleFeedStatus('Built-in financial intelligence active. No player data is uploaded.', 'neutral');
            return false;
        }
        setFinanceRuleFeedStatus('Checking GitHub financial intelligence feeds…', 'busy');
        const [rulesOk, policyOk] = await Promise.all([refreshFinancialRuleFeed(force), refreshFinancialPolicyFeed(force)]);
        const tone = rulesOk || policyOk ? 'good' : 'neutral';
        setFinanceRuleFeedStatus(`GitHub intelligence ${activeFinancialRuleVersion} · policy ${activeFinancialPolicyVersion}. No player data is uploaded.`, tone);
        return rulesOk || policyOk;
    }

    function ruleMatchesFinancialDescription(rule, description) {
        const text = String(description || '');
        const lower = text.toLowerCase();
        let matched;
        if (rule.match === 'contains') matched = lower.includes(String(rule.pattern).toLowerCase());
        else if (rule.match === 'startsWith') matched = lower.startsWith(String(rule.pattern).toLowerCase());
        else if (rule.match === 'equals') matched = lower === String(rule.pattern).toLowerCase();
        else {
            try { matched = (rule.patternRegex || new RegExp(rule.pattern, 'iu')).test(text); } catch (err) { matched = false; }
        }
        if (!matched || !rule.excludePattern) return matched;
        try { return !(rule.excludeRegex || new RegExp(rule.excludePattern, 'iu')).test(text); } catch (err) { return matched; }
    }

    function financialArchiveFilename(date = new Date()) {
        const pad = value => String(value).padStart(2, '0');
        return `MC Financial Archive ${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}-${pad(date.getMinutes())}.json`;
    }

    function buildFinancialArchiveExport(exportedAt = new Date()) {
        return {
            format: 'MissionChief Map Command Financial Archive',
            schema: 2,
            toolkitVersion: SCRIPT.version,
            exportedAt: exportedAt.toISOString(),
            identity: clonePlainData(financeVaultCredential()),
            store: clonePlainData(loadFinanceVaultStore()),
            notice: 'Contains locally stored MissionChief game-financial history. It does not contain the Discord webhook.'
        };
    }

    async function exportFinancialArchive() {
        const store = loadFinanceVaultStore();
        if (!Object.keys(store.profiles || {}).length) {
            showToast('No local financial history to export');
            return;
        }
        const accepted = pageWindow.confirm('FINANCIAL ARCHIVE EXPORT\n\nThis file contains your locally stored MissionChief game-financial history. It does not contain your Discord webhook.\n\nCreate the archive file now?');
        if (!accepted) return;
        const exportedAt = new Date();
        const json = JSON.stringify(buildFinancialArchiveExport(exportedAt), null, 2);
        const BlobConstructor = pageWindow.Blob || globalThis.Blob;
        downloadToolkitSettingsBlob(new BlobConstructor([json], { type: 'application/json' }), financialArchiveFilename(exportedAt));
        showToast('Financial archive exported');
    }

    function mergeFinanceVaultStores(existingStore, importedStore) {
        const result = { schema: FINANCE_VAULT_SCHEMA, profiles: { ...(existingStore?.profiles || {}) } };
        for (const [rawKey, rawVault] of Object.entries(importedStore?.profiles || {}).slice(0, 100)) {
            if (!rawVault || typeof rawVault !== 'object') continue;
            const player = {
                id: rawVault?.player?.id === undefined || rawVault?.player?.id === null || rawVault?.player?.id === '' ? null : String(rawVault.player.id).slice(0, 64),
                name: financeNormaliseText(rawVault?.player?.name).slice(0, 120)
            };
            const key = player.id || player.name ? financePlayerProfileKey(player) : String(rawKey || '').slice(0, 180);
            if (!key) continue;
            const imported = normaliseFinanceVault(rawVault, player, financeVaultCredential().deviceId);
            const current = normaliseFinanceVault(result.profiles[key], player, financeVaultCredential().deviceId);
            const transactions = new Map(current.transactions.map(entry => [entry.fingerprint, entry]));
            for (const entry of imported.transactions) transactions.set(entry.fingerprint, entry);
            const checkpoints = new Map(current.balanceCheckpoints.map(item => [`${item.timestamp}|${item.balance}`, item]));
            for (const item of imported.balanceCheckpoints) checkpoints.set(`${item.timestamp}|${item.balance}`, item);
            current.transactions = Array.from(transactions.values()).sort((a, b) => a.timestamp - b.timestamp || a.fingerprint.localeCompare(b.fingerprint));
            current.balanceCheckpoints = Array.from(checkpoints.values()).sort((a, b) => a.timestamp - b.timestamp).slice(-FINANCE_VAULT_MAX_CHECKPOINTS);
            const starts = [current.coverageStartMs, imported.coverageStartMs].filter(Number.isFinite);
            const ends = [current.coverageEndMs, imported.coverageEndMs].filter(Number.isFinite);
            current.coverageStartMs = starts.length ? Math.min(...starts) : null;
            current.coverageEndMs = ends.length ? Math.max(...ends) : null;
            current.lastFullScanAt = Math.max(current.lastFullScanAt, imported.lastFullScanAt);
            current.lastIncrementalScanAt = Math.max(current.lastIncrementalScanAt, imported.lastIncrementalScanAt);
            current.lastDeepScanAt = Math.max(current.lastDeepScanAt, imported.lastDeepScanAt);
            current.sourceLastPage = Math.max(current.sourceLastPage, imported.sourceLastPage);
            current.deepScanCursorPage = Math.max(current.deepScanCursorPage, imported.deepScanCursorPage);
            current.deepScanTotalPages = Math.max(current.deepScanTotalPages, imported.deepScanTotalPages);
            if (imported.deepScanInProgress && imported.deepScanCursorPage >= current.deepScanCursorPage) current.deepScanAnchor = imported.deepScanAnchor;
            current.deepScanInProgress = Boolean(current.deepScanInProgress || imported.deepScanInProgress);
            current.archiveComplete = Boolean(current.archiveComplete || imported.archiveComplete);
            current.archiveTruncated = Boolean(current.archiveTruncated || imported.archiveTruncated);
            if (current.archiveComplete) current.deepScanInProgress = false;
            current.droppedTransactions += imported.droppedTransactions;
            result.profiles[key] = current;
        }
        return result;
    }

    function importFinancialArchiveFile(file) {
        if (!file) return;
        if (Number(file.size) > 100 * 1024 * 1024) {
            showToast('Import failed: financial archive is too large');
            return;
        }
        const reader = new FileReader();
        reader.onload = () => {
            try {
                const parsed = JSON.parse(String(reader.result || ''));
                const importedStore = parsed?.store || parsed?.financialArchiveStore || parsed?.financialVaultStore;
                if (!importedStore?.profiles || typeof importedStore.profiles !== 'object') throw new Error('No Financial Archive history was found.');
                if (!pageWindow.confirm('FINANCIAL ARCHIVE IMPORT\n\nThe imported ledger will be merged with the local archive by player ID/name and transaction fingerprint. Existing entries will not be discarded.\n\nContinue?')) return;
                const merged = mergeFinanceVaultStores(loadFinanceVaultStore(), importedStore);
                saveFinanceVaultStore(merged);
                const importedIdentity = parsed?.identity || parsed?.integrations?.financialArchiveIdentity;
                if (importedIdentity && typeof importedIdentity === 'object') saveFinanceVaultCredential(normaliseImportedFinanceVaultCredential(importedIdentity));
                renderFinanceVaultStatus();
                invalidateDiscordFinancialPreview();
                showToast('Financial archive imported and merged');
            } catch (err) {
                showToast(`Archive import failed: ${err?.message || 'invalid file'}`);
            }
        };
        reader.onerror = () => showToast('Archive import failed: file could not be read');
        reader.readAsText(file);
    }

    function clearFinancialArchive() {
        const player = financePlayerIdentity({ userId: currentUserIdCached(), userName: financeVaultCredential().playerName });
        const key = financePlayerProfileKey(player);
        const store = loadFinanceVaultStore();
        if (!store.profiles[key]) {
            showToast('No local archive exists for this player');
            return;
        }
        if (!pageWindow.confirm(`Clear the locally stored Financial Archive for ${player.name || `player ${player.id || ''}`}?\n\nThis does not clear MissionChief's own ledger and cannot be undone unless you have an exported backup.`)) return;
        delete store.profiles[key];
        saveFinanceVaultStore(store);
        invalidateDiscordFinancialPreview();
        renderFinanceVaultStatus();
        showToast('Local financial archive cleared');
    }

    function cancelFinancialArchiveScan() {
        if (!financeArchiveScanBusy) {
            showToast('No deep financial scan is running');
            return;
        }
        financeArchiveScanCancelled = true;
        setFinanceVaultStatus('Stopping after the current ledger batch…', 'busy');
    }

    function renderFinanceVaultStatus() {
        const account = { userId: currentUserIdCached(), userName: financeVaultCredential().playerName };
        const player = financePlayerIdentity(account);
        const identity = financeVaultCredential();
        const vault = loadFinanceVault(player, identity.deviceId);
        const stats = financeVaultStats(vault);
        const node = document.querySelector(`#${SCRIPT.panelId} [data-finance-vault-summary]`);
        if (node) {
            const history = stats.firstTimestamp ? `${new Date(stats.firstTimestamp).toLocaleDateString('en-GB')} → ${new Date(stats.lastTimestamp).toLocaleDateString('en-GB')}` : 'No ledger history stored';
            const deepScan = stats.deepScanInProgress && stats.deepScanCursorPage
                ? `Deep scan resumable from page ${Math.min(stats.deepScanCursorPage + 1, stats.deepScanTotalPages || stats.sourceLastPage || stats.deepScanCursorPage + 1).toLocaleString('en-GB')}`
                : stats.lastDeepScanAt ? `Deep scan ${financeFormatTimeAgo(stats.lastDeepScanAt)}` : 'Deep scan not completed';
            const completeness = stats.archiveComplete ? 'FULL RANGE' : stats.archiveTruncated ? 'CAPPED' : stats.deepScanInProgress ? 'RESUMABLE' : 'PARTIAL';
            node.innerHTML = `<span><b>${stats.count.toLocaleString('en-GB')}</b> transactions</span><span><b>${stats.checkpoints.toLocaleString('en-GB')}</b> balance checks</span><span><b>${escapeHtml(activeFinancialRuleVersion)}</b> rules</span><span><b>${completeness}</b> archive</span><small>${escapeHtml(history)} · ${escapeHtml(deepScan)}${stats.sourceLastPage ? ` · ${stats.sourceLastPage.toLocaleString('en-GB')} source pages` : ''}</small>`;
        }
        setFinanceVaultStatus(financeVaultStatus, financeVaultStatusTone);
        setFinanceRuleFeedStatus(financeRuleFeedStatus, financeRuleFeedStatusTone);
    }


    /**
     * @template T
     * @param {string} key
     * @param {T} fallback
     * @returns {T}
     */
    function gmGetValueSafe(key, fallback) {
        try {
            if (typeof GM_getValue === 'function') return GM_getValue(key, fallback);
        } catch (err) {}
        return fallback;
    }

    function gmSetValueSafe(key, value) {
        try {
            if (typeof GM_setValue === 'function') {
                GM_setValue(key, value);
                return true;
            }
        } catch (err) {}
        return false;
    }

    function gmDeleteValueSafe(key) {
        try {
            if (typeof GM_deleteValue === 'function') {
                GM_deleteValue(key);
                return true;
            }
        } catch (err) {}
        return false;
    }

    function getDiscordWebhookUrl() {
        return String(gmGetValueSafe(SCRIPT.discordWebhookState, '') || '').trim();
    }

    function getLastDiscordReportAt() {
        const value = Number(gmGetValueSafe(SCRIPT.discordLastReportState, 0));
        return Number.isFinite(value) && value > 0 ? value : 0;
    }

    function normaliseDiscordWebhookUrl(rawValue) {
        const raw = String(rawValue || '').trim();
        if (!raw) return '';
        let parsed;
        try { parsed = new URL(raw); } catch (err) { throw new Error('The Discord webhook URL is not valid.'); }
        if (parsed.protocol !== 'https:' || !DISCORD_WEBHOOK_HOSTS.has(parsed.hostname.toLowerCase())) {
            throw new Error('Use a genuine HTTPS Discord webhook URL.');
        }
        if (!/^\/api(?:\/v\d+)?\/webhooks\/\d+\/[A-Za-z0-9._-]+\/?$/u.test(parsed.pathname)) {
            throw new Error('The URL does not contain a valid Discord webhook ID and token.');
        }
        parsed.hash = '';
        parsed.username = '';
        parsed.password = '';
        return parsed.toString();
    }

    function saveDiscordWebhookUrl(rawValue) {
        const normalised = normaliseDiscordWebhookUrl(rawValue);
        if (!normalised) {
            gmDeleteValueSafe(SCRIPT.discordWebhookState);
            return '';
        }
        if (!gmSetValueSafe(SCRIPT.discordWebhookState, normalised)) {
            throw new Error('Tampermonkey storage is unavailable.');
        }
        return normalised;
    }

    function readDiscordWebhookInput({ save = true } = {}) {
        const input = document.querySelector(`#${SCRIPT.panelId} [data-setting="discord-webhook"]`);
        const raw = String(input?.value || getDiscordWebhookUrl()).trim();
        return save ? saveDiscordWebhookUrl(raw) : normaliseDiscordWebhookUrl(raw);
    }

    function setDiscordStatus(message, tone = 'neutral') {
        discordFinanceStatus = String(message || '');
        discordFinanceStatusTone = ['neutral', 'good', 'bad', 'busy'].includes(tone) ? tone : 'neutral';
        const status = document.querySelector(`#${SCRIPT.panelId} [data-discord-status]`);
        if (status) {
            status.textContent = discordFinanceStatus;
            status.dataset.tone = discordFinanceStatusTone;
        }
    }

    function discordHttpRequest({ method = 'GET', url, data = null, headers = {} }) {
        return new Promise((resolve, reject) => {
            if (runtime.destroyed) {
                reject(new Error('Toolkit runtime stopped.'));
                return;
            }
            if (typeof GM_xmlhttpRequest !== 'function') {
                reject(new Error('Tampermonkey cross-origin requests are unavailable.'));
                return;
            }
            let request = null;
            let settled = false;
            const finish = (error, response = null) => {
                if (settled) return;
                settled = true;
                if (request) runtime.requests.delete(request);
                if (error) reject(error);
                else resolve(response);
            };
            try {
                request = GM_xmlhttpRequest({
                    method,
                    url,
                    data,
                    headers,
                    timeout: DISCORD_REQUEST_TIMEOUT_MS,
                    responseType: 'text',
                    onload: response => finish(null, response),
                    onerror: () => finish(new Error('Discord could not be reached.')),
                    ontimeout: () => finish(new Error('Discord request timed out.')),
                    onabort: () => finish(new Error('Discord request was cancelled.'))
                });
                if (!settled && request?.abort) runtime.requests.add(request);
            } catch (err) {
                finish(err instanceof Error ? err : new Error('Discord request could not be created.'));
            }
        });
    }

    function discordWebhookEndpoint(rawUrl, { wait = false, stripQuery = false } = {}) {
        const parsed = new URL(normaliseDiscordWebhookUrl(rawUrl));
        if (stripQuery) parsed.search = '';
        if (wait) parsed.searchParams.set('wait', 'true');
        return parsed.toString();
    }

    function parseDiscordError(response) {
        let detail = '';
        try {
            const body = JSON.parse(response?.responseText || '{}');
            detail = String(body?.message || body?.error || '').trim();
            if (body?.retry_after) detail = `Rate limited. Retry after ${Math.ceil(Number(body.retry_after) / 1000)} seconds.`;
        } catch (err) {}
        return detail || `Discord returned HTTP ${response?.status || 'error'}.`;
    }

    async function testDiscordWebhook() {
        if (discordFinanceBusy) return;
        discordFinanceBusy = true;
        setDiscordStatus('Checking the Discord webhook…', 'busy');
        try {
            const webhookUrl = readDiscordWebhookInput({ save: true });
            const response = await discordHttpRequest({
                method: 'GET',
                url: discordWebhookEndpoint(webhookUrl, { stripQuery: true })
            });
            if (response.status < 200 || response.status >= 300) throw new Error(parseDiscordError(response));
            let webhook = {};
            try { webhook = JSON.parse(response.responseText || '{}'); } catch (err) {}
            const label = String(webhook?.name || state.discordReport.webhookName || 'Discord webhook');
            setDiscordStatus(`Connected successfully: ${label}.`, 'good');
            showToast('Discord webhook connected');
        } catch (err) {
            setDiscordStatus(err?.message || 'Discord webhook test failed.', 'bad');
            showToast('Discord connection failed');
        } finally {
            discordFinanceBusy = false;
        }
    }

    function parseCreditInteger(value) {
        const text = String(value ?? '').replace(/\u2212/gu, '-').trim();
        if (!text) return 0;
        const negative = /(^|[^\d])-/u.test(text) || /^\s*\(/u.test(text);
        const digits = text.replace(/[^\d]/gu, '');
        if (!digits) return 0;
        const amount = Number(digits);
        return Number.isFinite(amount) ? (negative ? -amount : amount) : 0;
    }

    function parseCreditTimestamp(rawValue, fallbackText = '') {
        const raw = String(rawValue || '').trim();
        if (raw) {
            if (/^\d{10,13}$/u.test(raw)) {
                const numeric = Number(raw);
                const timestamp = raw.length === 10 ? numeric * 1000 : numeric;
                if (Number.isFinite(timestamp)) return timestamp;
            }
            const direct = Date.parse(raw);
            if (Number.isFinite(direct)) return direct;
        }
        const text = String(fallbackText || '').replace(/\s+/gu, ' ').trim();
        const match = text.match(/(\d{1,2})[./-](\d{1,2})[./-](\d{4})(?:\D+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/u);
        if (!match) return NaN;
        const [, day, month, year, hour = '0', minute = '0', second = '0'] = match;
        const parsed = new Date(Number(year), Number(month) - 1, Number(day), Number(hour), Number(minute), Number(second), 0).getTime();
        return Number.isFinite(parsed) ? parsed : NaN;
    }

    function parseCreditsListDocument(doc, pageNumber = 1) {
        const entries = [];
        let invalidTimestampCount = 0;
        const rows = Array.from(doc?.querySelectorAll?.('table tbody tr') || []);
        for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
            const row = rows[rowIndex];
            const cells = Array.from(row.children || []);
            if (cells.length < 3) continue;
            const amount = parseCreditInteger(cells[0]?.textContent);
            const description = String(cells[1]?.textContent || '').replace(/\s+/gu, ' ').trim();
            const dateLabel = String(cells[2]?.textContent || '').replace(/\s+/gu, ' ').trim();
            const rawTimestamp = String(cells[2]?.getAttribute?.('data-logged-at') || '').trim();
            if (!description || !amount) continue;
            const timestamp = parseCreditTimestamp(rawTimestamp, dateLabel);
            if (!Number.isFinite(timestamp)) invalidTimestampCount++;
            entries.push({ amount, description, dateLabel, rawTimestamp, timestamp, page: pageNumber, row: rowIndex });
        }
        let lastPage = 1;
        const paginationItems = Array.from(doc?.querySelectorAll?.('.pagination li') || []);
        for (const item of paginationItems) {
            const textPage = Number(String(item.textContent || '').replace(/[^\d]/gu, ''));
            if (Number.isFinite(textPage) && textPage > lastPage) lastPage = textPage;
            const href = item.querySelector?.('a[href]')?.getAttribute?.('href') || '';
            if (href) {
                try {
                    const url = new URL(href, document.baseURI || pageWindow.location.href);
                    const hrefPage = Number(url.searchParams.get('page'));
                    if (Number.isFinite(hrefPage) && hrefPage > lastPage) lastPage = hrefPage;
                } catch (err) {}
            }
        }
        return { entries, invalidTimestampCount, lastPage };
    }

    function normaliseFinancialOverviewHeader(value) {
        return financeNormaliseText(value).toLowerCase().replace(/[^a-z]/gu, '');
    }

    function parseFinancialOverviewDate(value) {
        const text = financeNormaliseText(value);
        const match = text.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})/u);
        if (!match) return null;
        const [, day, month, year] = match;
        const date = new Date(Number(year), Number(month) - 1, Number(day), 0, 0, 0, 0);
        if (date.getFullYear() !== Number(year) || date.getMonth() !== Number(month) - 1 || date.getDate() !== Number(day)) return null;
        const dayStartMs = date.getTime();
        return { dateKey: localIsoDate(date), dayStartMs, dayEndMs: addLocalDays(dayStartMs, 1), label: text };
    }

    function financialPaginationLastPage(doc) {
        let lastPage = 1;
        for (const item of Array.from(doc?.querySelectorAll?.('.pagination li') || [])) {
            const textPage = Number(String(item.textContent || '').replace(/[^\d]/gu, ''));
            if (Number.isFinite(textPage) && textPage > lastPage) lastPage = textPage;
            const href = item.querySelector?.('a[href]')?.getAttribute?.('href') || '';
            if (!href) continue;
            try {
                const url = new URL(href, document.baseURI || pageWindow.location.href);
                const hrefPage = Number(url.searchParams.get('page'));
                if (Number.isFinite(hrefPage) && hrefPage > lastPage) lastPage = hrefPage;
            } catch (err) {}
        }
        return lastPage;
    }

    function parseCreditOverviewDocument(doc, pageNumber = 1) {
        const rowsByDate = new Map();
        let malformedRowCount = 0;
        let duplicateDateCount = 0;
        const tables = Array.from(doc?.querySelectorAll?.('table') || []);
        const candidates = tables.length ? tables : [{
            querySelectorAll(selector) {
                if (selector === 'tbody tr') return doc?.querySelectorAll?.('table tbody tr') || [];
                return [];
            }
        }];
        for (const table of candidates) {
            let headers = Array.from(table?.querySelectorAll?.('thead th') || []);
            if (!headers.length) headers = Array.from(table?.querySelectorAll?.('tr th') || []);
            const normalisedHeaders = headers.map(header => normaliseFinancialOverviewHeader(header?.textContent));
            const findIndex = values => normalisedHeaders.findIndex(header => values.includes(header));
            let dateIndex = findIndex(['date', 'datum']);
            let revenueIndex = findIndex(['revenue', 'income', 'earnings']);
            let spendingIndex = findIndex(['spendings', 'spending', 'expenses', 'expenditure']);
            let sumIndex = findIndex(['sum', 'net', 'total', 'result']);
            const bodyRows = Array.from(table?.querySelectorAll?.('tbody tr') || []);
            if (!bodyRows.length) continue;
            if (dateIndex < 0 || revenueIndex < 0 || spendingIndex < 0) {
                const widest = Math.max(0, ...bodyRows.map(row => Array.from(row?.children || []).length));
                if (widest < 4) continue;
                [dateIndex, revenueIndex, spendingIndex, sumIndex] = [0, 1, 2, 3];
            }
            for (let rowIndex = 0; rowIndex < bodyRows.length; rowIndex++) {
                const cells = Array.from(bodyRows[rowIndex]?.children || []);
                if (cells.length <= Math.max(dateIndex, revenueIndex, spendingIndex, Math.max(0, sumIndex))) {
                    malformedRowCount++;
                    continue;
                }
                const date = parseFinancialOverviewDate(cells[dateIndex]?.textContent);
                const revenueText = financeNormaliseText(cells[revenueIndex]?.textContent);
                const spendingText = financeNormaliseText(cells[spendingIndex]?.textContent);
                const sumText = sumIndex >= 0 ? financeNormaliseText(cells[sumIndex]?.textContent) : '';
                if (!date || !revenueText || !spendingText) {
                    malformedRowCount++;
                    continue;
                }
                const revenue = Math.max(0, parseCreditInteger(revenueText));
                const parsedSpending = parseCreditInteger(spendingText);
                const spending = parsedSpending > 0 ? -parsedSpending : parsedSpending;
                const calculatedNet = revenue + spending;
                const net = sumText ? parseCreditInteger(sumText) : calculatedNet;
                if (Math.abs(net - calculatedNet) > 1) {
                    malformedRowCount++;
                    continue;
                }
                const row = {
                    ...date,
                    revenue,
                    spending,
                    net,
                    calculatedNet,
                    netMismatch: false,
                    page: Math.max(1, Number(pageNumber) || 1),
                    row: rowIndex
                };
                if (rowsByDate.has(date.dateKey)) {
                    duplicateDateCount++;
                    const existing = rowsByDate.get(date.dateKey);
                    if (existing.revenue !== row.revenue || existing.spending !== row.spending || existing.net !== row.net) malformedRowCount++;
                    continue;
                }
                rowsByDate.set(date.dateKey, row);
            }
            if (rowsByDate.size) break;
        }
        return {
            rows: Array.from(rowsByDate.values()).sort((a, b) => b.dayStartMs - a.dayStartMs),
            malformedRowCount,
            duplicateDateCount,
            lastPage: financialPaginationLastPage(doc)
        };
    }

    async function fetchCreditOverviewPage(pageNumber) {
        const page = Math.max(1, Math.round(Number(pageNumber) || 1));
        const attempts = Math.max(1, Math.min(5, Number(activeFinancialPolicy?.scan?.retryAttempts) || 3));
        let lastError = null;
        for (let attempt = 0; attempt < attempts; attempt++) {
            try {
                const path = page === 1 ? '/credits/overview' : `/credits/overview?page=${page}`;
                const result = await fetchSameOriginDocument(path);
                return parseCreditOverviewDocument(result.doc, page);
            } catch (err) {
                lastError = err;
                if (attempt >= attempts - 1) break;
                const delay = Math.min(4000, 350 * Math.pow(2, attempt) + Math.floor(Math.random() * 180));
                setDiscordStatus(`MissionChief credits overview page ${page.toLocaleString('en-GB')} needs another attempt…`, 'busy');
                if (!await runtimeDelay(delay)) throw new Error('Toolkit runtime stopped while retrying the credits overview.');
            }
        }
        throw lastError || new Error(`MissionChief credits overview page ${page} could not be read.`);
    }

    function financialOverviewCacheCovers(startMs, endMs, cache = financialOverviewCache) {
        if (!cache?.rows?.length || !Number.isFinite(Number(cache.coverageStartMs)) || !Number.isFinite(Number(cache.coverageEndMs))) return false;
        const requestedStart = localDayStart(Math.max(0, Number(startMs) || 0));
        const requestedEnd = localDayStart(Math.max(requestedStart, Number(endMs || Date.now()) - 1));
        return cache.coverageStartMs <= requestedStart && cache.coverageEndMs > requestedEnd;
    }

    async function fetchCreditOverview(requiredStartMs, requiredEndMs, options) {
        const force = Boolean(options?.force);
        const now = Date.now();
        const startMs = Math.max(0, Number(requiredStartMs) || 0);
        const endMs = Math.max(startMs + 1, Number(requiredEndMs) || now);
        if (!force && now - Number(financialOverviewCache.fetchedAt || 0) < FINANCE_OVERVIEW_CACHE_TTL_MS && financialOverviewCacheCovers(startMs, endMs)) {
            return { ...financialOverviewCache, rows: financialOverviewCache.rows.slice(), available: true, fromCache: true, coverageReached: true, error: '' };
        }
        const rowsByDate = new Map();
        let malformedRowCount = 0;
        let duplicateDateCount = 0;
        let pageCount = 0;
        let lastPage = 1;
        let failure = null;
        const targetStart = localDayStart(startMs);
        try {
            for (let page = 1; page <= Math.min(lastPage, FINANCE_OVERVIEW_MAX_PAGES); page++) {
                const parsed = await fetchCreditOverviewPage(page);
                pageCount++;
                lastPage = Math.max(lastPage, Number(parsed.lastPage) || 1);
                malformedRowCount += Number(parsed.malformedRowCount) || 0;
                duplicateDateCount += Number(parsed.duplicateDateCount) || 0;
                for (const row of parsed.rows) {
                    if (rowsByDate.has(row.dateKey)) {
                        duplicateDateCount++;
                        continue;
                    }
                    rowsByDate.set(row.dateKey, row);
                }
                const oldest = parsed.rows.length ? Math.min(...parsed.rows.map(row => row.dayStartMs)) : Infinity;
                if (startMs > 0 && oldest <= targetStart) break;
                if (page >= lastPage) break;
                if (page % FINANCE_FETCH_YIELD_EVERY === 0 && !await runtimeDelay(25)) throw new Error('Toolkit runtime stopped while reading the credits overview.');
            }
        } catch (err) {
            failure = err;
        }
        const rows = Array.from(rowsByDate.values()).sort((a, b) => b.dayStartMs - a.dayStartMs);
        if (!rows.length) {
            const cached = financialOverviewCache.rows?.length ? financialOverviewCache : null;
            if (cached) return { ...cached, rows: cached.rows.slice(), available: true, fromCache: true, stale: true, coverageReached: financialOverviewCacheCovers(startMs, endMs, cached), error: failure?.message || 'MissionChief credits overview was unavailable.' };
            return { available: false, rows: [], pageCount, lastPage, complete: false, coverageReached: false, malformedRowCount, duplicateDateCount, fromCache: false, stale: false, error: failure?.message || 'MissionChief credits overview was unavailable.' };
        }
        const coverageStartMs = Math.min(...rows.map(row => row.dayStartMs));
        const coverageEndMs = Math.max(...rows.map(row => row.dayEndMs));
        const complete = !failure && pageCount >= Math.min(lastPage, FINANCE_OVERVIEW_MAX_PAGES);
        const cache = {
            fetchedAt: now,
            rows,
            pageCount,
            lastPage,
            coverageStartMs,
            coverageEndMs,
            complete,
            malformedRowCount,
            duplicateDateCount
        };
        financialOverviewCache = cache;
        return { ...cache, rows: rows.slice(), available: true, fromCache: false, stale: false, coverageReached: financialOverviewCacheCovers(startMs, endMs, cache), error: failure?.message || '' };
    }

    function financialLedgerAnchor(entries, count = 3) {
        return entries.slice(0, Math.max(1, count)).map(entry =>
            `${entry.timestamp}|${entry.amount}|${entry.description}|${entry.rawTimestamp || entry.dateLabel}`
        ).join('||');
    }

    async function fetchSameOriginDocument(pathOrUrl) {
        const url = new URL(pathOrUrl, document.baseURI || pageWindow.location.href);
        if (url.origin !== pageWindow.location.origin) throw new Error('Blocked an unexpected external financial-data URL.');
        const response = await runtimeFetch(url.href, {
            method: 'GET',
            credentials: 'same-origin',
            cache: 'no-store',
            headers: { Accept: 'text/html,application/xhtml+xml' }
        });
        if (!response.ok) throw new Error(`MissionChief returned HTTP ${response.status} for ${url.pathname}.`);
        const html = await response.text();
        return { doc: new DOMParser().parseFromString(html, 'text/html'), url: url.href };
    }

    async function fetchCreditLedgerPage(pageNumber) {
        const page = Math.max(1, Math.round(Number(pageNumber) || 1));
        const attempts = Math.max(1, Math.min(5, Number(activeFinancialPolicy?.scan?.retryAttempts) || 3));
        let lastError = null;
        for (let attempt = 0; attempt < attempts; attempt++) {
            try {
                const path = page === 1 ? '/credits' : `/credits?page=${page}`;
                const result = await fetchSameOriginDocument(path);
                return parseCreditsListDocument(result.doc, page);
            } catch (err) {
                lastError = err;
                if (attempt >= attempts - 1) break;
                const delay = Math.min(4000, 350 * Math.pow(2, attempt) + Math.floor(Math.random() * 180));
                setDiscordStatus(`MissionChief ledger page ${page.toLocaleString('en-GB')} needs another attempt…`, 'busy');
                if (!await runtimeDelay(delay)) throw new Error('Toolkit runtime stopped while retrying the financial ledger.');
            }
        }
        throw lastError || new Error(`MissionChief ledger page ${page} could not be read.`);
    }

    async function fetchCreditAccount() {
        try {
            const response = await runtimeFetch(new URL('/api/credits', document.baseURI || pageWindow.location.href).href, {
                method: 'GET',
                credentials: 'same-origin',
                cache: 'no-store',
                headers: { Accept: 'application/json' }
            });
            if (!response.ok) return null;
            const data = await response.json();
            const balance = Number(data?.credits_user_current);
            return {
                currentBalance: Number.isFinite(balance) ? Math.round(balance) : null,
                userName: String(data?.user_name || '').trim(),
                userId: Number(data?.user_id) || null
            };
        } catch (err) {
            return null;
        }
    }

    function localIsoDate(date = new Date()) {
        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    }

    function localDayStart(value = Date.now()) {
        const date = new Date(value);
        date.setHours(0, 0, 0, 0);
        return date.getTime();
    }

    function addLocalDays(timestamp, days) {
        const date = new Date(timestamp);
        date.setDate(date.getDate() + Number(days || 0));
        return date.getTime();
    }

    function parseLocalDateInput(value) {
        const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})$/u);
        if (!match) return NaN;
        const [, year, month, day] = match;
        return new Date(Number(year), Number(month) - 1, Number(day), 0, 0, 0, 0).getTime();
    }

    function formatReportDate(date = new Date()) {
        try { return date.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }); }
        catch (err) { return localIsoDate(date); }
    }

    function formatReportDateTime(timestamp) {
        try { return new Date(timestamp).toLocaleString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }); }
        catch (err) { return new Date(timestamp).toISOString(); }
    }

    function formatPeriodRange(startMs, endMs) {
        const inclusiveEnd = Math.max(startMs, endMs - 1);
        const sameDay = localIsoDate(new Date(startMs)) === localIsoDate(new Date(inclusiveEnd));
        if (sameDay) return `${formatReportDate(new Date(startMs))} · ${new Date(startMs).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}–${new Date(inclusiveEnd).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
        return `${formatReportDateTime(startMs)} → ${formatReportDateTime(inclusiveEnd)}`;
    }

    function formatSignedCredits(value) {
        const amount = Math.round(Number(value) || 0);
        const sign = amount > 0 ? '+' : amount < 0 ? '-' : '';
        return `${sign}${Math.abs(amount).toLocaleString('en-GB')} Credits`;
    }

    function formatPlainCredits(value) {
        return `${Math.max(0, Math.round(Number(value) || 0)).toLocaleString('en-GB')} Credits`;
    }

    function formatSignedCompactCredits(value) {
        const amount = Math.abs(Math.round(Number(value) || 0));
        const sign = Number(value) < 0 ? '-' : Number(value) > 0 ? '+' : '';
        if (amount >= 1_000_000_000) return `${sign}${(amount / 1_000_000_000).toFixed(amount >= 10_000_000_000 ? 1 : 2).replace(/\.0+$/u, '')}B`;
        if (amount >= 1_000_000) return `${sign}${(amount / 1_000_000).toFixed(amount >= 10_000_000 ? 1 : 2).replace(/\.0+$/u, '')}M`;
        if (amount >= 1_000) return `${sign}${(amount / 1_000).toFixed(amount >= 100_000 ? 0 : amount >= 10_000 ? 1 : 2).replace(/\.0+$/u, '')}K`;
        return `${sign}${amount.toLocaleString('en-GB')}`;
    }

    function reportTone(net) {
        return net > 0 ? 'positive' : net < 0 ? 'negative' : 'neutral';
    }

    function resolveFinancialPeriod() {
        const now = Date.now();
        const todayStart = localDayStart(now);
        const periodId = FINANCE_PERIOD_IDS.has(state.discordReport.period) ? state.discordReport.period : 'today';
        let startMs = todayStart;
        let endMs = now;
        let label = 'Today';
        let note = '';
        if (periodId === 'yesterday') {
            startMs = addLocalDays(todayStart, -1);
            endMs = todayStart;
            label = 'Yesterday';
        } else if (periodId === 'last24') {
            startMs = now - 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 24 Hours';
        } else if (periodId === 'last7') {
            startMs = now - 7 * 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 7 Days';
        } else if (periodId === 'last30') {
            startMs = now - 30 * 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 30 Days';
        } else if (periodId === 'last90') {
            startMs = now - 90 * 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 90 Days';
        } else if (periodId === 'last180') {
            startMs = now - 180 * 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 180 Days';
        } else if (periodId === 'last365') {
            startMs = now - 365 * 24 * 60 * 60 * 1000;
            endMs = now;
            label = 'Last 365 Days';
        } else if (periodId === 'allAvailable') {
            startMs = 0;
            endMs = now;
            label = 'All Available MissionChief History';
            note = 'The Toolkit uses the complete local archive when available and otherwise performs a deep scan across every MissionChief credit-ledger page accessible to the account.';
        } else if (periodId === 'session') {
            startMs = FINANCE_SESSION_STARTED_AT;
            endMs = now;
            label = 'Current Toolkit Session';
        } else if (periodId === 'sinceLast') {
            const lastReportAt = getLastDiscordReportAt();
            startMs = lastReportAt || FINANCE_SESSION_STARTED_AT;
            endMs = now;
            label = lastReportAt ? 'Since Last Discord Report' : 'Since Toolkit Session Start';
            if (!lastReportAt) note = 'No previous successful Discord report timestamp was stored, so the current toolkit session was used.';
        } else if (periodId === 'custom') {
            const start = parseLocalDateInput(state.discordReport.customStart);
            const end = parseLocalDateInput(state.discordReport.customEnd);
            if (!Number.isFinite(start) || !Number.isFinite(end)) throw new Error('Select valid custom start and end dates.');
            if (end < start) throw new Error('The custom end date cannot be earlier than the start date.');
            startMs = start;
            endMs = Math.min(now, addLocalDays(end, 1));
            if (endMs <= startMs) throw new Error('The selected custom date range contains no elapsed time.');
            if (endMs - startMs > 90 * 24 * 60 * 60 * 1000) throw new Error('Custom financial reports are limited to 90 days per run.');
            label = 'Custom Financial Period';
        }
        const durationMs = Math.max(1, endMs - startMs);
        let comparisonEndMs = startMs;
        let comparisonStartMs = startMs - durationMs;
        if (periodId === 'allAvailable') {
            comparisonStartMs = 0;
            comparisonEndMs = 0;
        }
        if (periodId === 'today') {
            comparisonStartMs = addLocalDays(todayStart, -1);
            comparisonEndMs = Math.min(todayStart, comparisonStartMs + durationMs);
        } else if (periodId === 'yesterday') {
            comparisonEndMs = startMs;
            comparisonStartMs = addLocalDays(startMs, -1);
        }
        return {
            id: periodId,
            startMs,
            endMs,
            durationMs,
            comparisonStartMs,
            comparisonEndMs,
            label,
            rangeLabel: formatPeriodRange(startMs, endMs),
            comparisonRangeLabel: formatPeriodRange(comparisonStartMs, comparisonEndMs),
            note
        };
    }

    function normaliseFinancialLedgerEntry(entry) {
        if (!Number.isFinite(entry?.timestamp)) return null;
        const amount = Math.round(Number(entry.amount) || 0);
        const description = financeNormaliseText(entry.description);
        const dateLabel = financeNormaliseText(entry.dateLabel);
        const rawTimestamp = financeNormaliseText(entry.rawTimestamp);
        const sourceKey = `${entry.timestamp}|${amount}|${description.toLowerCase()}|${rawTimestamp || dateLabel}`;
        return { ...entry, amount, description, dateLabel, rawTimestamp, sourceKey };
    }

    async function fetchFinancialLedger(requiredStartMs, attempt = 0, forceFull = false, exhaustive = false) {
        const account = await fetchCreditAccount();
        const player = financePlayerIdentity(account);
        const identity = ensureFinanceVaultCredential(player);
        let vault = loadFinanceVault(player, identity.deviceId);
        const vaultStats = financeVaultStats(vault);
        const wantsAllAvailable = Number(requiredStartMs) <= 0;
        const deepMode = Boolean(exhaustive || (wantsAllAvailable && !vault.archiveComplete));
        const effectiveRequiredStart = wantsAllAvailable && Number.isFinite(Number(vault.coverageStartMs)) ? Number(vault.coverageStartMs) : Number(requiredStartMs);
        const canUseIncremental = Boolean(
            state.financialVault.enabled &&
            !forceFull &&
            !deepMode &&
            vaultStats.count &&
            Number.isFinite(Number(vault.coverageStartMs)) &&
            Number(vault.coverageStartMs) <= effectiveRequiredStart &&
            Number.isFinite(Number(vault.coverageEndMs))
        );
        const knownSourceKeys = canUseIncremental ? new Set(vault.transactions.map(entry => entry.sourceKey)) : new Set();
        const vaultLatestTimestamp = canUseIncremental ? Number(vault.coverageEndMs) || vaultStats.lastTimestamp || 0 : 0;
        let pendingEntries = [];
        let invalidTimestampCount = 0;
        let lastPage = 1;
        let fetchedPages = 0;
        let oldestTimestamp = Infinity;
        let reachedStart = false;
        let firstPageAnchor = '';
        let overlapFound = false;
        let scanCancelled = false;
        let scanLimitReached;
        let lastProcessedPage = 0;
        const scanOccurrenceCounts = new Map();
        const absorbPage = (parsed, page) => {
            fetchedPages++;
            lastProcessedPage = Math.max(lastProcessedPage, page);
            invalidTimestampCount += parsed.invalidTimestampCount;
            let pageOverlap = 0;
            let pageOldest = Infinity;
            for (const entry of parsed.entries) {
                const normalisedEntry = normaliseFinancialLedgerEntry(entry);
                if (!normalisedEntry) continue;
                const occurrence = (scanOccurrenceCounts.get(normalisedEntry.sourceKey) || 0) + 1;
                scanOccurrenceCounts.set(normalisedEntry.sourceKey, occurrence);
                pendingEntries.push({ ...normalisedEntry, occurrence });
                if (normalisedEntry.timestamp < oldestTimestamp) oldestTimestamp = normalisedEntry.timestamp;
                if (normalisedEntry.timestamp < pageOldest) pageOldest = normalisedEntry.timestamp;
                if (canUseIncremental && knownSourceKeys.has(normalisedEntry.sourceKey)) pageOverlap++;
            }
            reachedStart = Number.isFinite(oldestTimestamp) && oldestTimestamp <= effectiveRequiredStart;
            if (canUseIncremental && pageOverlap >= 3 && Number.isFinite(pageOldest) && pageOldest <= vaultLatestTimestamp) overlapFound = true;
        };
        const persistCheckpoint = ({ final = false, completeRange = false } = {}) => {
            if (!state.financialVault.enabled || (!pendingEntries.length && !final)) return;
            vault = mergeFinanceVaultEntries(vault, pendingEntries, {
                coverageStartMs: Number.isFinite(oldestTimestamp) ? oldestTimestamp : null,
                coverageEndMs: Date.now(),
                fullScan: forceFull || deepMode,
                deepScan: deepMode && final && completeRange,
                sourceLastPage: lastPage,
                deepScanCursorPage: deepMode ? lastProcessedPage : null,
                deepScanTotalPages: deepMode ? lastPage : null,
                deepScanAnchor: deepMode ? firstPageAnchor : null,
                deepScanInProgress: deepMode ? !completeRange : null,
                archiveComplete: final ? completeRange : null,
                currentBalance: final ? account?.currentBalance : null
            });
            pendingEntries = [];
        };
        const firstPage = await fetchCreditLedgerPage(1);
        lastPage = Math.max(1, firstPage.lastPage || 1);
        firstPageAnchor = financialLedgerAnchor(firstPage.entries);
        let deepScanStartPage = 2;
        const resumableDeepScan = Boolean(
            deepMode &&
            vault.deepScanInProgress &&
            vault.deepScanAnchor &&
            vault.deepScanAnchor === firstPageAnchor &&
            Number(vault.deepScanTotalPages) === lastPage &&
            Number(vault.deepScanCursorPage) >= 1 &&
            Number(vault.deepScanCursorPage) < lastPage
        );
        if (resumableDeepScan) {
            deepScanStartPage = Math.max(2, Number(vault.deepScanCursorPage) + 1);
            lastProcessedPage = Number(vault.deepScanCursorPage);
            oldestTimestamp = Number.isFinite(Number(vault.coverageStartMs)) ? Number(vault.coverageStartMs) : Infinity;
            for (const existing of vault.transactions) {
                const sourceKey = String(existing.sourceKey || '');
                if (!sourceKey) continue;
                scanOccurrenceCounts.set(sourceKey, Math.max(scanOccurrenceCounts.get(sourceKey) || 0, Number(existing.occurrence) || 1));
            }
            setFinanceVaultStatus(`Resuming deep scan from MissionChief ledger page ${deepScanStartPage.toLocaleString('en-GB')}…`, 'busy');
        } else {
            absorbPage(firstPage, 1);
        }
        if (deepMode) {
            const configuredCap = Math.max(100, Math.min(FINANCE_DEEP_SCAN_HARD_PAGE_CAP, Number(activeFinancialPolicy?.scan?.pageCap) || FINANCE_DEEP_SCAN_HARD_PAGE_CAP));
            const targetLastPage = Math.min(lastPage, configuredCap);
            const batchSize = Math.max(1, Math.min(FINANCE_DEEP_SCAN_HARD_BATCH_CAP, Number(activeFinancialPolicy?.scan?.batchSize) || 3));
            const checkpointPages = Math.max(20, Math.min(500, Number(activeFinancialPolicy?.scan?.checkpointPages) || FINANCE_SCAN_CHECKPOINT_PAGES));
            scanLimitReached = targetLastPage < lastPage;
            for (let cursor = deepScanStartPage; cursor <= targetLastPage; cursor += batchSize) {
                if (financeArchiveScanCancelled) {
                    scanCancelled = true;
                    break;
                }
                const pages = Array.from({ length: Math.min(batchSize, targetLastPage - cursor + 1) }, (_, index) => cursor + index);
                const results = await Promise.all(pages.map(page => fetchCreditLedgerPage(page)));
                for (let index = 0; index < pages.length; index++) absorbPage(results[index], pages[index]);
                if (state.financialVault.enabled && lastProcessedPage % checkpointPages < batchSize) persistCheckpoint();
                setDiscordStatus(`Deep MissionChief ledger scan · page ${lastProcessedPage.toLocaleString('en-GB')} of ${lastPage.toLocaleString('en-GB')} · ${Math.round(lastProcessedPage / Math.max(1, targetLastPage) * 100)}%`, 'busy');
                setFinanceVaultStatus(`Deep scan reading page ${lastProcessedPage.toLocaleString('en-GB')} of ${lastPage.toLocaleString('en-GB')}…`, 'busy');
                if (lastProcessedPage % 15 === 0 && !await runtimeDelay(45)) throw new Error('Toolkit runtime stopped while deep-scanning the financial ledger.');
            }
            reachedStart = !scanCancelled && !scanLimitReached && lastProcessedPage >= lastPage;
        } else {
            let page = 2;
            while (page <= Math.min(lastPage, FINANCE_MAX_LEDGER_PAGES)) {
                if (reachedStart || overlapFound) break;
                if (canUseIncremental && page > FINANCE_INCREMENTAL_MAX_PAGES) break;
                const parsed = await fetchCreditLedgerPage(page);
                absorbPage(parsed, page);
                if (page % FINANCE_FETCH_YIELD_EVERY === 0) {
                    setDiscordStatus(`${canUseIncremental ? 'Synchronising new ledger activity' : 'Reading MissionChief ledger'} · page ${page.toLocaleString('en-GB')} of ${lastPage.toLocaleString('en-GB')}…`, 'busy');
                    if (!await runtimeDelay(35)) throw new Error('Toolkit runtime stopped while reading the financial ledger.');
                }
                page++;
            }
            scanLimitReached = lastProcessedPage >= FINANCE_MAX_LEDGER_PAGES && lastProcessedPage < lastPage;
        }
        if (canUseIncremental && !overlapFound && !reachedStart && lastProcessedPage < lastPage) {
            setDiscordStatus('Local archive overlap was not found. Performing one complete requested-range scan…', 'busy');
            return fetchFinancialLedger(requiredStartMs, attempt, true, false);
        }
        let ledgerStable = true;
        if (fetchedPages > 1 && firstPageAnchor) {
            const verificationPage = await fetchCreditLedgerPage(1);
            ledgerStable = financialLedgerAnchor(verificationPage.entries) === firstPageAnchor;
            if (!ledgerStable && !deepMode && attempt < 1) {
                setDiscordStatus('New credit activity appeared during the scan. Restarting once for an accurate report…', 'busy');
                if (!await runtimeDelay(80)) throw new Error('Toolkit runtime stopped while stabilising the financial ledger.');
                return fetchFinancialLedger(requiredStartMs, attempt + 1, forceFull, false);
            }
            if (!ledgerStable && deepMode) {
                setFinanceVaultStatus('MissionChief added ledger activity during the deep scan. Progress was retained and the next run will safely rescan from the changed first page.', 'neutral');
            }
        }
        if (!pendingEntries.length && !vault.transactions.length) throw new Error('MissionChief’s timestamped credit ledger could not be read.');
        const coverageReachedThisScan = deepMode
            ? (!scanCancelled && !scanLimitReached && ledgerStable && lastProcessedPage >= lastPage)
            : (ledgerStable && (reachedStart || overlapFound || lastProcessedPage >= lastPage));
        persistCheckpoint({ final: true, completeRange: coverageReachedThisScan });
        if (!state.financialVault.enabled) {
            pendingEntries = decorateFinancialEntries(pendingEntries);
        }
        const combinedEntries = state.financialVault.enabled
            ? vault.transactions.filter(entry => wantsAllAvailable || entry.timestamp >= Math.min(effectiveRequiredStart, Number(vault.coverageStartMs) || effectiveRequiredStart))
            : pendingEntries;
        const coverageReached = wantsAllAvailable
            ? (state.financialVault.enabled ? Boolean(vault.archiveComplete) : coverageReachedThisScan)
            : (state.financialVault.enabled
                ? Number.isFinite(Number(vault.coverageStartMs)) && Number(vault.coverageStartMs) <= effectiveRequiredStart
                : coverageReachedThisScan);
        const complete = coverageReached && ledgerStable && invalidTimestampCount === 0 && !scanCancelled && !scanLimitReached;
        const stats = financeVaultStats(vault);
        if (state.financialVault.enabled) {
            const mode = deepMode ? 'Deep' : canUseIncremental ? 'Incremental' : 'Requested-range';
            const suffix = scanCancelled
                ? ' Scan stopped; collected pages were retained.'
                : scanLimitReached
                    ? ' Page safety cap reached.'
                    : !ledgerStable
                        ? ' New ledger activity appeared during the scan; progress remains resumable.'
                        : '';
            setFinanceVaultStatus(`${mode} archive scan stored ${stats.count.toLocaleString('en-GB')} transactions.${suffix}`, scanCancelled || scanLimitReached ? 'neutral' : 'good');
            renderFinanceVaultStatus();
        }
        return {
            entries: combinedEntries,
            pageCount: fetchedPages,
            lastPage,
            invalidTimestampCount,
            oldestTimestamp: combinedEntries.length ? combinedEntries[0].timestamp : null,
            coverageReached,
            ledgerStable,
            scanRetries: attempt,
            scanCancelled,
            scanLimitReached,
            archiveComplete: Boolean(vault.archiveComplete),
            archiveTruncated: Boolean(vault.archiveTruncated),
            droppedTransactions: Number(vault.droppedTransactions) || 0,
            complete,
            account,
            vault,
            vaultTransactionCount: stats.count,
            ledgerSource: state.financialVault.enabled
                ? (deepMode ? 'Local archive + deep MissionChief scan' : canUseIncremental ? 'Local archive + incremental MissionChief scan' : 'Local archive + requested-range scan')
                : (deepMode ? 'Direct deep MissionChief ledger scan' : 'Direct MissionChief ledger scan')
        };
    }

    async function scanFinancialArchive() {
        if (financeArchiveScanBusy) {
            showToast('A financial archive scan is already running');
            return false;
        }
        financeArchiveScanBusy = true;
        financeArchiveScanCancelled = false;
        setFinanceVaultStatus('Starting deep scan of every available MissionChief ledger page…', 'busy');
        try {
            const ledger = await fetchFinancialLedger(0, 0, false, true);
            const stats = financeVaultStats(ledger.vault);
            const result = ledger.scanCancelled
                ? `Deep scan stopped safely at ${stats.count.toLocaleString('en-GB')} archived transactions.`
                : ledger.scanLimitReached
                    ? `Deep scan reached the configured safety cap with ${stats.count.toLocaleString('en-GB')} transactions archived.`
                    : `Deep scan complete: ${stats.count.toLocaleString('en-GB')} transactions across ${ledger.lastPage.toLocaleString('en-GB')} MissionChief ledger pages.`;
            setFinanceVaultStatus(result, ledger.scanCancelled || ledger.scanLimitReached ? 'neutral' : 'good');
            showToast(ledger.scanCancelled ? 'Financial deep scan stopped' : 'Financial deep scan complete');
            invalidateDiscordFinancialPreview();
            renderFinanceVaultStatus();
            return !ledger.scanCancelled;
        } catch (err) {
            setFinanceVaultStatus(err?.message || 'Deep financial scan failed.', 'bad');
            showToast('Financial deep scan failed');
            return false;
        } finally {
            financeArchiveScanBusy = false;
            financeArchiveScanCancelled = false;
        }
    }

    function classifyFinancialTransaction(transaction) {
        const description = financeNormaliseText(transaction?.description);
        const amount = Number(transaction?.amount) || 0;
        const direction = amount > 0 ? 'income' : 'spending';
        for (const rule of activeFinancialRules) {
            if (rule.direction !== direction) continue;
            if (!ruleMatchesFinancialDescription(rule, description)) continue;
            return {
                key: rule.key,
                label: rule.label,
                kind: direction,
                missionType: rule.missionType || '',
                accountingGroup: rule.accountingGroup,
                confidence: clamp(rule.confidence, 0, 1, 0.5),
                ruleId: rule.id,
                source: rule.source || 'built-in'
            };
        }
        const fallback = activeFinancialFallbacks[direction] || BUILTIN_FINANCIAL_FALLBACKS[direction];
        return {
            key: fallback.key,
            label: fallback.label,
            kind: direction,
            missionType: fallback.missionType || '',
            accountingGroup: fallback.accountingGroup,
            confidence: clamp(fallback.confidence, 0, 1, 0.25),
            ruleId: fallback.id || `fallback-${direction}`,
            source: 'fallback'
        };
    }

    function buildFinancialBuckets(transactions, startMs, endMs) {
        const duration = Math.max(1, endMs - startMs);
        const useHourly = duration <= 48 * 60 * 60 * 1000;
        const targetBuckets = useHourly ? 12 : duration <= 31 * 86400000 ? 31 : 24;
        const unitMs = useHourly ? 60 * 60 * 1000 : 24 * 60 * 60 * 1000;
        const bucketMs = Math.max(unitMs, Math.ceil(duration / targetBuckets / unitMs) * unitMs);
        const count = Math.max(1, Math.min(targetBuckets, Math.ceil(duration / bucketMs)));
        const buckets = Array.from({ length: count }, (_, index) => ({
            start: startMs + index * bucketMs,
            end: Math.min(endMs, startMs + (index + 1) * bucketMs),
            income: 0,
            operatingIncome: 0,
            otherIncome: 0,
            operatingExpense: 0,
            capitalInvestment: 0,
            spending: 0,
            operatingResult: 0,
            net: 0,
            label: ''
        }));
        for (const transaction of transactions) {
            const index = Math.min(count - 1, Math.max(0, Math.floor((transaction.timestamp - startMs) / bucketMs)));
            if (!buckets[index] || transaction.timestamp < startMs || transaction.timestamp >= endMs) continue;
            const category = transaction.classification || classifyFinancialTransaction(transaction);
            const amount = Number(transaction.amount) || 0;
            if (amount > 0) {
                buckets[index].income += amount;
                if (category.accountingGroup === 'operatingIncome') buckets[index].operatingIncome += amount;
                else buckets[index].otherIncome += amount;
            } else {
                const absolute = Math.abs(amount);
                buckets[index].spending += absolute;
                if (category.accountingGroup === 'capitalInvestment') buckets[index].capitalInvestment += absolute;
                else buckets[index].operatingExpense += absolute;
            }
            buckets[index].operatingResult = buckets[index].operatingIncome + buckets[index].otherIncome - buckets[index].operatingExpense;
            buckets[index].net += amount;
        }
        for (const bucket of buckets) {
            const date = new Date(bucket.start);
            bucket.label = useHourly
                ? date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
                : date.toLocaleDateString('en-GB', duration > 180 * 86400000 ? { month: 'short', year: '2-digit' } : { day: 'numeric', month: 'short' });
        }
        return buckets;
    }

    function calculateActiveHours(transactions) {
        const activeQuarterHours = new Set();
        for (const entry of transactions) {
            if (!Number.isFinite(Number(entry.timestamp))) continue;
            activeQuarterHours.add(Math.floor(Number(entry.timestamp) / (15 * 60 * 1000)));
        }
        return Math.max(0.25, activeQuarterHours.size * 0.25);
    }

    function medianNumber(values) {
        const sorted = values.filter(Number.isFinite).sort((a, b) => a - b);
        if (!sorted.length) return 0;
        const middle = Math.floor(sorted.length / 2);
        return sorted.length % 2 ? sorted[middle] : Math.round((sorted[middle - 1] + sorted[middle]) / 2);
    }

    function standardDeviation(values) {
        const finite = values.filter(Number.isFinite);
        if (finite.length < 2) return 0;
        const average = finite.reduce((sum, value) => sum + value, 0) / finite.length;
        return Math.sqrt(finite.reduce((sum, value) => sum + Math.pow(value - average, 2), 0) / finite.length);
    }

    function summariseFinancialTransactions(transactions, period) {
        const incomeCategoryMap = new Map();
        const spendingCategoryMap = new Map();
        const operatingExpenseCategoryMap = new Map();
        const capitalCategoryMap = new Map();
        const topPayouts = [];
        const missionPayoutValues = [];
        const unclassifiedEntries = [];
        let income = 0;
        let spending = 0;
        let operatingIncome = 0;
        let otherIncome = 0;
        let operatingExpense = 0;
        let capitalInvestment = 0;
        let incomeCount = 0;
        let spendingCount = 0;
        let missionCount = 0;
        let missionIncome = 0;
        let allianceIncome = 0;
        let personalIncome = 0;
        let transportIncome = 0;
        let largestReward = 0;
        let smallestReward = Infinity;
        let largestSpend = 0;
        let classificationWeight = 0;
        let classificationWeightedScore = 0;
        let unclassifiedAmount = 0;
        let unclassifiedCount = 0;
        let hasMissionPayout = false;
        const addCategory = (map, category, amount) => {
            const existing = map.get(category.key) || { key: category.key, label: category.label, accountingGroup: category.accountingGroup, total: 0, count: 0 };
            existing.total += Math.abs(amount);
            existing.count += 1;
            map.set(category.key, existing);
        };
        const addTopPayout = entry => {
            topPayouts.push(entry);
            topPayouts.sort((a, b) => b.amount - a.amount);
            if (topPayouts.length > 8) topPayouts.length = 8;
        };
        const classifiedTransactions = [];
        for (const sourceEntry of transactions) {
            const amount = Number(sourceEntry.amount) || 0;
            if (!amount) continue;
            const category = classifyFinancialTransaction(sourceEntry);
            const entry = { ...sourceEntry, classification: category };
            classifiedTransactions.push(entry);
            const weight = Math.max(1, Math.abs(amount));
            classificationWeight += weight;
            classificationWeightedScore += weight * category.confidence;
            const isUnclassified = category.ruleId.startsWith('fallback') || category.key.startsWith('unclassified');
            if (isUnclassified) {
                unclassifiedAmount += Math.abs(amount);
                unclassifiedCount += 1;
                if (unclassifiedEntries.length < 20) unclassifiedEntries.push(entry);
            }
            if (amount > 0) {
                income += amount;
                incomeCount += 1;
                addCategory(incomeCategoryMap, category, amount);
                if (category.accountingGroup === 'operatingIncome') operatingIncome += amount;
                else otherIncome += amount;
                if (category.missionType) {
                    missionCount += 1;
                    missionIncome += amount;
                    hasMissionPayout = true;
                    missionPayoutValues.push(amount);
                    largestReward = Math.max(largestReward, amount);
                    smallestReward = Math.min(smallestReward, amount);
                    addTopPayout(entry);
                }
                if (category.missionType === 'alliance') allianceIncome += amount;
                if (category.missionType === 'personal') personalIncome += amount;
                if (category.missionType === 'transport') transportIncome += amount;
            } else {
                const absolute = Math.abs(amount);
                spending += absolute;
                spendingCount += 1;
                largestSpend = Math.max(largestSpend, absolute);
                addCategory(spendingCategoryMap, category, amount);
                if (category.accountingGroup === 'capitalInvestment') {
                    capitalInvestment += absolute;
                    addCategory(capitalCategoryMap, category, amount);
                } else {
                    operatingExpense += absolute;
                    addCategory(operatingExpenseCategoryMap, category, amount);
                }
            }
        }
        if (!hasMissionPayout) {
            topPayouts.length = 0;
            largestReward = 0;
            smallestReward = Infinity;
            for (const entry of classifiedTransactions) {
                if (entry.amount <= 0) continue;
                largestReward = Math.max(largestReward, entry.amount);
                smallestReward = Math.min(smallestReward, entry.amount);
                addTopPayout(entry);
            }
        }
        const net = income - spending;
        const operatingResult = operatingIncome + otherIncome - operatingExpense;
        const calendarHours = Math.max(1 / 60, period.durationMs / (60 * 60 * 1000));
        const calendarDays = Math.max(1 / 24, calendarHours / 24);
        const activeHours = calculateActiveHours(classifiedTransactions);
        const buckets = buildFinancialBuckets(classifiedTransactions, period.startMs, period.endMs);
        const classificationConfidence = classificationWeight ? Math.round((classificationWeightedScore / classificationWeight) * 1000) / 10 : 100;
        const operatingMarginPercent = income ? Math.round((operatingResult / income) * 1000) / 10 : operatingExpense ? -100 : 0;
        const capitalInvestmentRatioPercent = income ? Math.round((capitalInvestment / income) * 1000) / 10 : capitalInvestment ? 100 : 0;
        const topIncomeCategory = Array.from(incomeCategoryMap.values()).sort((a, b) => b.total - a.total)[0] || null;
        const incomeConcentrationPercent = income && topIncomeCategory ? Math.round((topIncomeCategory.total / income) * 1000) / 10 : 0;
        const bucketIncomeValues = buckets.map(bucket => bucket.income);
        const incomeVolatilityPercent = bucketIncomeValues.length && income
            ? Math.round((standardDeviation(bucketIncomeValues) / Math.max(1, bucketIncomeValues.reduce((sum, value) => sum + value, 0) / bucketIncomeValues.length)) * 1000) / 10
            : 0;
        return {
            transactions: classifiedTransactions,
            incomeCategories: Array.from(incomeCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            spendingCategories: Array.from(spendingCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            operatingExpenseCategories: Array.from(operatingExpenseCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            capitalCategories: Array.from(capitalCategoryMap.values()).sort((a, b) => b.total - a.total || b.count - a.count),
            income,
            spending,
            operatingIncome,
            otherIncome,
            operatingExpense,
            capitalInvestment,
            operatingResult,
            net,
            incomeCount,
            spendingCount,
            activityCount: incomeCount + spendingCount,
            missionCount,
            missionIncome,
            averageIncome: incomeCount ? Math.round(income / incomeCount) : 0,
            averageSpend: spendingCount ? Math.round(spending / spendingCount) : 0,
            averageMissionReward: missionCount ? Math.round(missionIncome / missionCount) : 0,
            medianMissionReward: medianNumber(missionPayoutValues),
            largestReward,
            smallestReward: Number.isFinite(smallestReward) ? smallestReward : 0,
            largestSpend,
            allianceIncome,
            personalIncome,
            transportIncome,
            allianceIncomePercent: income ? Math.round((allianceIncome / income) * 1000) / 10 : 0,
            personalIncomePercent: income ? Math.round((personalIncome / income) * 1000) / 10 : 0,
            incomePerHour: Math.round(income / calendarHours),
            activeIncomePerHour: Math.round(income / activeHours),
            activeHours: Math.round(activeHours * 100) / 100,
            calendarHours: Math.round(calendarHours * 100) / 100,
            calendarDays: Math.round(calendarDays * 1000) / 1000,
            classificationConfidence,
            unclassifiedAmount,
            unclassifiedCount,
            unclassifiedEntries,
            operatingMarginPercent,
            capitalInvestmentRatioPercent,
            incomeConcentrationPercent,
            incomeVolatilityPercent,
            topIncomeCategory,
            topPayouts,
            buckets
        };
    }

    function financialOverviewDayIsAuthoritative(dayStartMs, period) {
        const dayStart = Number(dayStartMs);
        const dayEnd = addLocalDays(dayStart, 1);
        if (!Number.isFinite(dayStart) || period.startMs > dayStart) return false;
        const todayStart = localDayStart();
        if (dayStart === todayStart) return period.endMs >= Date.now() - 10 * 60 * 1000;
        return period.endMs >= dayEnd;
    }

    function reconcileFinancialOverview(summary, transactions, period, overview) {
        if (summary?.overviewAudit) return summary;
        const base = { ...summary, buckets: summary.buckets.map(bucket => ({ ...bucket })) };
        const unavailable = !overview?.available || !Array.isArray(overview.rows) || !overview.rows.length;
        const emptyAudit = {
            available: !unavailable,
            status: unavailable ? 'unavailable' : 'not-applicable',
            label: unavailable ? 'Credits overview unavailable; detailed ledger totals retained' : 'No complete overview day falls inside this period',
            rowsUsed: 0,
            rowsCompared: 0,
            pageCount: Number(overview?.pageCount) || 0,
            lastPage: Number(overview?.lastPage) || 0,
            coverageReached: Boolean(overview?.coverageReached),
            malformedRowCount: Number(overview?.malformedRowCount) || 0,
            duplicateDateCount: Number(overview?.duplicateDateCount) || 0,
            ledgerIncome: summary.income,
            ledgerSpending: summary.spending,
            ledgerNet: summary.net,
            overviewIncome: 0,
            overviewSpending: 0,
            overviewNet: 0,
            incomeVariance: 0,
            spendingVariance: 0,
            netVariance: 0,
            unresolvedVariance: 0,
            days: [],
            error: String(overview?.error || '')
        };
        if (unavailable) return { ...base, overviewAudit: emptyAudit };
        const ledgerDays = new Map();
        for (const entry of transactions) {
            const timestamp = Number(entry?.timestamp);
            if (!Number.isFinite(timestamp) || timestamp < period.startMs || timestamp >= period.endMs) continue;
            const dateKey = localIsoDate(new Date(timestamp));
            const day = ledgerDays.get(dateKey) || { income: 0, spending: 0, net: 0 };
            const amount = Number(entry.amount) || 0;
            if (amount > 0) day.income += amount;
            else day.spending += amount;
            day.net += amount;
            ledgerDays.set(dateKey, day);
        }
        const auditDays = [];
        let coveredLedgerIncome = 0;
        let coveredLedgerSpending = 0;
        let coveredLedgerNet = 0;
        let overviewIncome = 0;
        let overviewSpending = 0;
        let overviewNet = 0;
        for (const row of overview.rows) {
            if (row.dayEndMs <= period.startMs || row.dayStartMs >= period.endMs) continue;
            if (!financialOverviewDayIsAuthoritative(row.dayStartMs, period)) continue;
            const ledgerDay = ledgerDays.get(row.dateKey) || { income: 0, spending: 0, net: 0 };
            const incomeVariance = row.revenue - ledgerDay.income;
            const spendingVariance = row.spending - ledgerDay.spending;
            const netVariance = row.net - ledgerDay.net;
            auditDays.push({
                dateKey: row.dateKey,
                dayStartMs: row.dayStartMs,
                ledgerIncome: ledgerDay.income,
                ledgerSpending: ledgerDay.spending,
                ledgerNet: ledgerDay.net,
                overviewIncome: row.revenue,
                overviewSpending: row.spending,
                overviewNet: row.net,
                incomeVariance,
                spendingVariance,
                netVariance,
                exact: Math.abs(incomeVariance) <= 1 && Math.abs(spendingVariance) <= 1 && Math.abs(netVariance) <= 1
            });
            coveredLedgerIncome += ledgerDay.income;
            coveredLedgerSpending += ledgerDay.spending;
            coveredLedgerNet += ledgerDay.net;
            overviewIncome += row.revenue;
            overviewSpending += row.spending;
            overviewNet += row.net;
            const midpoint = row.dayStartMs + 12 * 60 * 60 * 1000;
            const bucket = base.buckets.find(candidate => midpoint >= candidate.start && midpoint < candidate.end);
            if (bucket) {
                bucket.income += incomeVariance;
                bucket.spending += Math.abs(row.spending) - Math.abs(ledgerDay.spending);
                bucket.net += netVariance;
            }
        }
        if (!auditDays.length) return { ...base, overviewAudit: emptyAudit };
        const incomeVariance = overviewIncome - coveredLedgerIncome;
        const spendingVariance = overviewSpending - coveredLedgerSpending;
        const netVariance = overviewNet - coveredLedgerNet;
        const income = summary.income + incomeVariance;
        const spending = Math.max(0, summary.spending + Math.abs(overviewSpending) - Math.abs(coveredLedgerSpending));
        const net = income - spending;
        const status = Math.abs(netVariance) <= 1 && auditDays.every(day => day.exact)
            ? (overview.coverageReached ? 'reconciled' : 'partial')
            : 'variance';
        const label = status === 'reconciled'
            ? `${auditDays.length.toLocaleString('en-GB')} overview day${auditDays.length === 1 ? '' : 's'} fully reconciled`
            : status === 'partial'
                ? `${auditDays.length.toLocaleString('en-GB')} overview day${auditDays.length === 1 ? '' : 's'} reconciled; requested range exceeds fetched overview coverage`
                : `Overview checkpoint variance ${formatSignedCredits(netVariance)}`;
        const calendarHours = Math.max(1 / 60, Number(summary.calendarHours) || period.durationMs / 3600000);
        const activeHours = Math.max(0.25, Number(summary.activeHours) || 0.25);
        const bucketIncomeValues = base.buckets.map(bucket => bucket.income);
        return {
            ...base,
            income,
            spending,
            net,
            incomePerHour: Math.round(income / calendarHours),
            activeIncomePerHour: Math.round(income / activeHours),
            operatingMarginPercent: income ? Math.round((summary.operatingResult / income) * 1000) / 10 : summary.operatingExpense ? -100 : 0,
            capitalInvestmentRatioPercent: income ? Math.round((summary.capitalInvestment / income) * 1000) / 10 : summary.capitalInvestment ? 100 : 0,
            allianceIncomePercent: income ? Math.round((summary.allianceIncome / income) * 1000) / 10 : 0,
            personalIncomePercent: income ? Math.round((summary.personalIncome / income) * 1000) / 10 : 0,
            incomeConcentrationPercent: income && summary.topIncomeCategory ? Math.round((summary.topIncomeCategory.total / income) * 1000) / 10 : 0,
            incomeVolatilityPercent: bucketIncomeValues.length && income
                ? Math.round((standardDeviation(bucketIncomeValues) / Math.max(1, bucketIncomeValues.reduce((sum, value) => sum + value, 0) / bucketIncomeValues.length)) * 1000) / 10
                : 0,
            overviewAudit: {
                available: true,
                status,
                label,
                rowsUsed: auditDays.length,
                rowsCompared: auditDays.length,
                pageCount: Number(overview.pageCount) || 0,
                lastPage: Number(overview.lastPage) || 0,
                coverageReached: Boolean(overview.coverageReached),
                malformedRowCount: Number(overview.malformedRowCount) || 0,
                duplicateDateCount: Number(overview.duplicateDateCount) || 0,
                ledgerIncome: coveredLedgerIncome,
                ledgerSpending: Math.abs(coveredLedgerSpending),
                ledgerNet: coveredLedgerNet,
                overviewIncome,
                overviewSpending: Math.abs(overviewSpending),
                overviewNet,
                incomeVariance,
                spendingVariance,
                netVariance,
                unresolvedVariance: Math.abs(netVariance) <= 1 ? 0 : netVariance,
                days: auditDays,
                error: String(overview.error || '')
            }
        };
    }

    function percentageChange(current, previous) {
        const currentValue = Number(current) || 0;
        const previousValue = Number(previous) || 0;
        if (!previousValue) return currentValue ? null : 0;
        return ((currentValue - previousValue) / Math.abs(previousValue)) * 100;
    }

    function formatPercentageChange(value) {
        if (value === null || !Number.isFinite(value)) return 'New activity';
        const rounded = Math.round(value * 10) / 10;
        return `${rounded > 0 ? '+' : ''}${rounded.toLocaleString('en-GB')}%`;
    }

    function buildFinancialComparison(current, previous) {
        return {
            incomeChange: percentageChange(current.income, previous.income),
            operatingResultChange: percentageChange(current.operatingResult, previous.operatingResult),
            capitalInvestmentChange: percentageChange(current.capitalInvestment, previous.capitalInvestment),
            spendingChange: percentageChange(current.spending, previous.spending),
            netChange: percentageChange(current.net, previous.net),
            missionChange: current.missionCount - previous.missionCount,
            averageRewardChange: percentageChange(current.averageMissionReward, previous.averageMissionReward),
            activeVelocityChange: percentageChange(current.activeIncomePerHour, previous.activeIncomePerHour),
            currentNet: current.net,
            previousNet: previous.net
        };
    }

    function calculateVaultReconciliation(vault, period, currentTransactions, currentBalance) {
        const checkpoints = Array.isArray(vault?.balanceCheckpoints) ? vault.balanceCheckpoints.slice().sort((a, b) => a.timestamp - b.timestamp) : [];
        let startCheckpoint = null;
        let endCheckpoint = null;
        for (const checkpoint of checkpoints) {
            if (checkpoint.timestamp <= period.startMs) startCheckpoint = checkpoint;
            if (checkpoint.timestamp >= period.endMs && !endCheckpoint) endCheckpoint = checkpoint;
        }
        if (!endCheckpoint && Number.isFinite(Number(currentBalance)) && Math.abs(Date.now() - period.endMs) < 10 * 60 * 1000) {
            endCheckpoint = { timestamp: Date.now(), balance: Math.round(currentBalance) };
        }
        if (!startCheckpoint || !endCheckpoint || endCheckpoint.timestamp <= startCheckpoint.timestamp) {
            return { reconciled: false, difference: null, label: 'Reconstructed from current balance and ledger', startCheckpoint, endCheckpoint };
        }
        const movement = currentTransactions
            .filter(entry => entry.timestamp > startCheckpoint.timestamp && entry.timestamp <= endCheckpoint.timestamp)
            .reduce((sum, entry) => sum + Number(entry.amount || 0), 0);
        const difference = Math.round((endCheckpoint.balance - startCheckpoint.balance) - movement);
        return {
            reconciled: Math.abs(difference) <= 1,
            difference,
            label: Math.abs(difference) <= 1 ? 'Reconciled against saved balance checkpoints' : `Checkpoint variance ${formatSignedCredits(difference)}`,
            startCheckpoint,
            endCheckpoint
        };
    }

    function financialScoreLabel(score) {
        if (score >= 90) return { grade: 'A+', label: 'Exceptional command' };
        if (score >= 82) return { grade: 'A', label: 'Strong command' };
        if (score >= 74) return { grade: 'B+', label: 'Healthy expansion' };
        if (score >= 66) return { grade: 'B', label: 'Stable position' };
        if (score >= 56) return { grade: 'C+', label: 'Mixed position' };
        if (score >= 45) return { grade: 'C', label: 'Watch position' };
        if (score >= 32) return { grade: 'D', label: 'Financial pressure' };
        return { grade: 'F', label: 'Critical pressure' };
    }

    function calculateFinancialScorecard(summary, comparison, { complete = true, balanceAvailable = true, reconciled = false, closingBalance = null } = {}) {
        const incomeTrend = comparison?.incomeChange;
        let revenue = 65;
        if (Number.isFinite(incomeTrend)) revenue += Math.max(-25, Math.min(25, incomeTrend / 2));
        if (summary.activeIncomePerHour > summary.incomePerHour * 1.5) revenue += 4;
        revenue = Math.round(clamp(revenue, 0, 100, 65));
        let efficiency = 55 + summary.operatingMarginPercent * 0.45;
        if (summary.operatingExpense === 0 && summary.income > 0) efficiency += 8;
        efficiency = Math.round(clamp(efficiency, 0, 100, 55));
        const dailyOperatingExpense = summary.operatingExpense / Math.max(1 / 24, Number(summary.calendarDays) || 1 / 24);
        const runwayDays = balanceAvailable && dailyOperatingExpense > 0 ? Math.max(0, Number(closingBalance) || 0) / dailyOperatingExpense : null;
        let liquidity = balanceAvailable ? 65 : 40;
        if (runwayDays !== null) liquidity += Math.max(-30, Math.min(30, (runwayDays - 7) * 2));
        liquidity = Math.round(clamp(liquidity, 0, 100, 60));
        const capexRatio = summary.capitalInvestmentRatioPercent;
        let growth = summary.capitalInvestment > 0 ? 72 : 58;
        if (capexRatio > 200) growth -= 18;
        else if (capexRatio > 120) growth -= 8;
        else if (capexRatio >= 20 && capexRatio <= 100) growth += 10;
        growth = Math.round(clamp(growth, 0, 100, 60));
        let confidence = summary.classificationConfidence;
        if (!complete) confidence -= 18;
        if (!balanceAvailable) confidence -= 8;
        if (reconciled) confidence += 5;
        confidence = Math.round(clamp(confidence, 0, 100, 75));
        const overall = Math.round(revenue * 0.25 + efficiency * 0.25 + liquidity * 0.20 + growth * 0.15 + confidence * 0.15);
        const assessment = financialScoreLabel(overall);
        return {
            overall,
            grade: assessment.grade,
            label: assessment.label,
            revenue,
            efficiency,
            liquidity,
            growth,
            confidence,
            runwayDays: runwayDays === null ? null : Math.round(runwayDays * 10) / 10,
            operatingMarginPercent: summary.operatingMarginPercent
        };
    }

    function calculateFinancialDrawdown(openingBalance, transactions) {
        if (!Number.isFinite(Number(openingBalance))) return { peakBalance: null, lowBalance: null, largestDrawdown: null, largestDrawdownPercent: null };
        let balance = Number(openingBalance);
        let peak = balance;
        let low = balance;
        let largestDrawdown = 0;
        let largestDrawdownPercent = 0;
        for (const entry of transactions.slice().sort((a, b) => a.timestamp - b.timestamp)) {
            balance += Number(entry.amount) || 0;
            peak = Math.max(peak, balance);
            low = Math.min(low, balance);
            const drawdown = Math.max(0, peak - balance);
            if (drawdown > largestDrawdown) {
                largestDrawdown = drawdown;
                largestDrawdownPercent = peak ? drawdown / peak * 100 : 0;
            }
        }
        return { peakBalance: Math.round(peak), lowBalance: Math.round(low), largestDrawdown: Math.round(largestDrawdown), largestDrawdownPercent: Math.round(largestDrawdownPercent * 10) / 10 };
    }

    function buildFinancialRiskAlerts(summary, comparison, context = {}) {
        const alerts = [];
        const add = (severity, title, detail) => alerts.push({ severity, title, detail });
        const risk = activeFinancialPolicy?.risk || BUILTIN_FINANCIAL_POLICY.risk;
        if (!context.ledgerComplete) add('high', 'Partial ledger coverage', 'The requested period was not fully verified from the MissionChief ledger or local archive.');
        if (context.overviewStatus === 'variance') add('high', 'Credits overview variance', `MissionChief daily aggregates differ from the detailed ledger by ${formatSignedCredits(context.overviewVariance)}. Aggregate totals use the overview checkpoint while categories remain ledger-derived.`);
        else if (context.overviewStatus === 'partial') add('medium', 'Partial overview coverage', 'Only the complete daily rows available from MissionChief were reconciled; the remaining period retains detailed-ledger totals.');
        else if (context.overviewStatus === 'unavailable') add('low', 'Credits overview unavailable', 'The report remains operational using the detailed ledger, but daily aggregate verification could not be completed.');
        if (context.archiveTruncated) add('high', 'Local archive capacity reached', `${Number(context.droppedTransactions || 0).toLocaleString('en-GB')} older transactions were not retained locally. Run the report directly against MissionChief for the widest currently accessible range.`);
        if (context.scanLimitReached) add('high', 'Ledger page safety cap reached', 'MissionChief exposed more ledger pages than the configured deep-scan safety cap. The report is extensive but not complete.');
        if (context.scanCancelled) add('medium', 'Deep scan stopped', 'The report uses all pages collected before the scan was stopped. Those pages remain stored in the local archive.');
        if (summary.classificationConfidence < risk.classificationCritical) add('high', 'Low classification confidence', `${summary.unclassifiedCount.toLocaleString('en-GB')} transactions remain uncertain; review the original descriptions.`);
        else if (summary.classificationConfidence < risk.classificationWarning) add('medium', 'Classification review advised', `${summary.classificationConfidence.toLocaleString('en-GB')}% weighted classification confidence.`);
        if (summary.operatingResult < 0) add('high', 'Negative operating result', `Operating activity is ${formatSignedCredits(summary.operatingResult)} before capital investment.`);
        if (summary.capitalInvestmentRatioPercent >= risk.capitalIncomeRatio && summary.capitalInvestment > 0) add('medium', 'Aggressive capital deployment', `Capital investment is ${summary.capitalInvestmentRatioPercent.toLocaleString('en-GB')}% of period income.`);
        if (summary.allianceIncomePercent >= risk.allianceConcentration) add('medium', 'Alliance income concentration', `${summary.allianceIncomePercent.toLocaleString('en-GB')}% of income is alliance-derived.`);
        if (summary.incomeConcentrationPercent >= risk.categoryConcentration) add('medium', 'Revenue concentration', `${summary.incomeConcentrationPercent.toLocaleString('en-GB')}% of income came from ${summary.topIncomeCategory?.label || 'one category'}.`);
        if (summary.incomeVolatilityPercent >= risk.volatilityWarning) add('low', 'High income volatility', `Bucket-to-bucket income volatility is ${summary.incomeVolatilityPercent.toLocaleString('en-GB')}%.`);
        if (comparison && Number.isFinite(comparison.incomeChange) && comparison.incomeChange <= risk.revenueContraction) add('high', 'Revenue contraction', `Income fell ${Math.abs(Math.round(comparison.incomeChange * 10) / 10).toLocaleString('en-GB')}% versus the previous equivalent period.`);
        if (Number.isFinite(context.drawdown?.largestDrawdownPercent) && context.drawdown.largestDrawdownPercent >= risk.drawdownWarning) add('medium', 'Material reserve drawdown', `Largest reconstructed drawdown was ${context.drawdown.largestDrawdownPercent.toLocaleString('en-GB')}%.`);
        if (context.scorecard?.runwayDays !== null && context.scorecard?.runwayDays < risk.runwayCriticalDays) add('high', 'Low operating runway', `Current reserve covers approximately ${context.scorecard.runwayDays.toLocaleString('en-GB')} days at the observed operating-expense pace.`);
        if (!alerts.length) add('good', 'No material alerts', 'No configured financial risk threshold was triggered for this period.');
        return alerts.slice(0, 8);
    }

    function buildFinancialForecast(summary, period, closingBalance) {
        const durationDays = Math.max(1 / 24, period.durationMs / 86400000);
        const dailyIncome = summary.income / durationDays;
        const dailyOperatingResult = summary.operatingResult / durationDays;
        const sevenDayIncome = Math.round(dailyIncome * 7);
        const thirtyDayIncome = Math.round(dailyIncome * 30);
        const recoveryDays = summary.capitalInvestment > 0 && dailyOperatingResult > 0 ? summary.capitalInvestment / dailyOperatingResult : null;
        let endOfDayIncome = null;
        if (period.id === 'today') {
            const elapsedHours = Math.max(0.25, (Date.now() - localDayStart()) / 3600000);
            endOfDayIncome = Math.round(summary.income / elapsedHours * 24);
        }
        const confidence = summary.activityCount >= 100 && durationDays >= 7 ? 'HIGH' : summary.activityCount >= 25 && durationDays >= 1 ? 'MEDIUM' : 'LOW';
        return {
            dailyIncome: Math.round(dailyIncome),
            dailyOperatingResult: Math.round(dailyOperatingResult),
            sevenDayIncome,
            thirtyDayIncome,
            endOfDayIncome,
            recoveryDays: recoveryDays === null ? null : Math.round(recoveryDays * 10) / 10,
            projectedSevenDayBalance: Number.isFinite(Number(closingBalance)) ? Math.round(Number(closingBalance) + dailyOperatingResult * 7) : null,
            confidence
        };
    }


    function currentFinancialReportSignature() {
        return JSON.stringify({
            period: state.discordReport.period,
            customStart: state.discordReport.customStart,
            customEnd: state.discordReport.customEnd,
            includeChart: state.discordReport.includeChart,
            includeComparison: state.discordReport.includeComparison,
            reportMode: state.discordReport.reportMode,
            includeForecast: state.discordReport.includeForecast,
            includeRisk: state.discordReport.includeRisk,
            topCategories: state.discordReport.topCategories,
            ruleVersion: activeFinancialRuleVersion,
            policyVersion: activeFinancialPolicyVersion,
            sinceLastAnchor: state.discordReport.period === 'sinceLast' ? getLastDiscordReportAt() : 0
        });
    }

    async function buildFinancialReport() {
        let period = resolveFinancialPeriod();
        const comparisonEnabled = state.discordReport.includeComparison && period.id !== 'allAvailable';
        const requiredStartMs = comparisonEnabled ? period.comparisonStartMs : period.startMs;
        setDiscordStatus('Updating GitHub intelligence and reading the MissionChief Financial Archive…', 'busy');
        await refreshFinancialIntelligenceFeeds(false);
        const allAvailable = period.id === 'allAvailable';
        if (allAvailable) {
            financeArchiveScanBusy = true;
            financeArchiveScanCancelled = false;
        }
        let ledger;
        try {
            ledger = await fetchFinancialLedger(requiredStartMs, 0, false, false);
        } finally {
            if (allAvailable) {
                financeArchiveScanBusy = false;
                financeArchiveScanCancelled = false;
            }
        }
        if (allAvailable) {
            const oldest = ledger.oldestTimestamp || ledger.entries[0]?.timestamp || Date.now();
            period = {
                ...period,
                startMs: oldest,
                durationMs: Math.max(1, period.endMs - oldest),
                comparisonStartMs: 0,
                comparisonEndMs: 0,
                rangeLabel: formatPeriodRange(oldest, period.endMs),
                comparisonRangeLabel: 'Not applicable'
            };
        }
        const currentTransactions = [];
        const previousTransactions = [];
        let afterPeriodNet = 0;
        const now = Date.now();
        for (const entry of ledger.entries) {
            if (entry.timestamp >= period.startMs && entry.timestamp < period.endMs) currentTransactions.push(entry);
            else if (comparisonEnabled && entry.timestamp >= period.comparisonStartMs && entry.timestamp < period.comparisonEndMs) previousTransactions.push(entry);
            if (entry.timestamp >= period.endMs && entry.timestamp <= now) afterPeriodNet += entry.amount;
        }
        const overview = await fetchCreditOverview(comparisonEnabled ? period.comparisonStartMs : period.startMs, period.endMs);
        const currentLedgerSummary = summariseFinancialTransactions(currentTransactions, period);
        const current = reconcileFinancialOverview(currentLedgerSummary, currentTransactions, period, overview);
        const previousPeriod = { ...period, startMs: period.comparisonStartMs, endMs: period.comparisonEndMs, durationMs: period.durationMs };
        const previousLedgerSummary = comparisonEnabled ? summariseFinancialTransactions(previousTransactions, previousPeriod) : null;
        const previous = previousLedgerSummary ? reconcileFinancialOverview(previousLedgerSummary, previousTransactions, previousPeriod, overview) : null;
        const comparison = previous ? buildFinancialComparison(current, previous) : null;
        const account = ledger.account;
        const currentBalance = Number.isFinite(account?.currentBalance) ? account.currentBalance : null;
        const closingBalance = currentBalance === null ? null : currentBalance - afterPeriodNet;
        const openingBalance = closingBalance === null ? null : closingBalance - current.net;
        const balanceAvailable = openingBalance !== null && closingBalance !== null;
        const reconciliation = calculateVaultReconciliation(ledger.vault, period, ledger.entries, currentBalance);
        const overviewAudit = current.overviewAudit || { status: 'unavailable', label: 'Credits overview unavailable', unresolvedVariance: 0 };
        const reconciliationLabel = `${balanceAvailable ? reconciliation.label : 'Balance unavailable'} · ${overviewAudit.label}`;
        const drawdown = calculateFinancialDrawdown(openingBalance, current.transactions);
        const aggregateVerified = ['reconciled', 'not-applicable'].includes(overviewAudit.status);
        const scorecard = calculateFinancialScorecard(current, comparison, { complete: ledger.complete && overviewAudit.status !== 'partial', balanceAvailable, reconciled: reconciliation.reconciled && aggregateVerified, closingBalance });
        let forecastSummary = current;
        let forecastPeriod = period;
        if (state.discordReport.includeForecast && period.durationMs > 30 * 86400000) {
            const recentStart = Math.max(period.startMs, period.endMs - 30 * 86400000);
            const recentTransactions = currentTransactions.filter(entry => entry.timestamp >= recentStart);
            forecastPeriod = { ...period, startMs: recentStart, durationMs: Math.max(1, period.endMs - recentStart), id: 'recent30' };
            forecastSummary = summariseFinancialTransactions(recentTransactions, forecastPeriod);
        }
        const forecast = state.discordReport.includeForecast ? { ...buildFinancialForecast(forecastSummary, forecastPeriod, closingBalance), basisDays: Math.max(1, Math.round(forecastPeriod.durationMs / 86400000)) } : null;
        const report = {
            generatedAt: Date.now(),
            signature: currentFinancialReportSignature(),
            period,
            reportDate: localIsoDate(),
            reportDateLabel: `${period.label} · ${period.rangeLabel}`,
            userName: account?.userName || ledger.vault?.player?.name || '',
            userId: account?.userId || ledger.vault?.player?.id || null,
            currentBalance,
            openingBalance,
            closingBalance,
            reconciliationDifference: reconciliation.difference,
            reconciled: reconciliation.reconciled,
            balanceCalculated: balanceAvailable,
            reconciliationLabel,
            ledgerComplete: ledger.complete,
            ledgerCoverageReached: ledger.coverageReached,
            ledgerPages: ledger.pageCount,
            ledgerLastPage: ledger.lastPage,
            ledgerStable: ledger.ledgerStable,
            ledgerScanRetries: ledger.scanRetries,
            ledgerScanCancelled: ledger.scanCancelled,
            ledgerScanLimitReached: ledger.scanLimitReached,
            ledgerSource: ledger.ledgerSource,
            archiveComplete: ledger.archiveComplete,
            archiveTruncated: ledger.archiveTruncated,
            droppedTransactions: ledger.droppedTransactions,
            vaultTransactionCount: ledger.vaultTransactionCount,
            invalidTimestampCount: ledger.invalidTimestampCount,
            overviewAvailable: Boolean(overviewAudit.available),
            overviewStatus: overviewAudit.status,
            overviewLabel: overviewAudit.label,
            overviewRowsUsed: overviewAudit.rowsUsed,
            overviewPages: overviewAudit.pageCount,
            overviewLastPage: overviewAudit.lastPage,
            overviewCoverageReached: overviewAudit.coverageReached,
            overviewMalformedRows: overviewAudit.malformedRowCount,
            overviewDuplicateDates: overviewAudit.duplicateDateCount,
            overviewIncome: overviewAudit.overviewIncome,
            overviewSpending: overviewAudit.overviewSpending,
            overviewNet: overviewAudit.overviewNet,
            ledgerCheckpointIncome: overviewAudit.ledgerIncome,
            ledgerCheckpointSpending: overviewAudit.ledgerSpending,
            ledgerCheckpointNet: overviewAudit.ledgerNet,
            overviewIncomeVariance: overviewAudit.incomeVariance,
            overviewSpendingVariance: overviewAudit.spendingVariance,
            overviewNetVariance: overviewAudit.netVariance,
            overviewUnresolvedVariance: overviewAudit.unresolvedVariance,
            overviewAudit,
            aggregateReconciled: aggregateVerified,
            comparison,
            previous,
            scorecard,
            grade: { score: scorecard.overall, grade: scorecard.grade, label: scorecard.label, marginPercent: scorecard.operatingMarginPercent },
            forecast,
            drawdown,
            chartBlob: null,
            ...current
        };
        report.riskAlerts = state.discordReport.includeRisk ? buildFinancialRiskAlerts(current, comparison, {
            ledgerComplete: ledger.complete,
            drawdown,
            scorecard,
            archiveTruncated: ledger.archiveTruncated,
            droppedTransactions: ledger.droppedTransactions,
            scanLimitReached: ledger.scanLimitReached,
            scanCancelled: ledger.scanCancelled,
            overviewStatus: overviewAudit.status,
            overviewVariance: overviewAudit.unresolvedVariance
        }) : [];
        report.chartBlob = state.discordReport.includeChart ? await buildFinancialChartBlob(report) : null;
        return report;
    }

    function escapeDiscordMarkdown(value) {
        return String(value || '')
            .replace(/\\/gu, '\\\\')
            .replace(/([`*_~>|])/gu, '\\$1')
            .replace(/@/gu, '@\u200b');
    }

    function truncateDiscord(value, maximum = DISCORD_MAX_FIELD_LENGTH) {
        const text = String(value || '');
        return text.length <= maximum ? text : `${text.slice(0, Math.max(0, maximum - 1))}…`;
    }

    function buildDiscordCategoryBreakdown(entries, prefix, limit) {
        const rows = entries.slice(0, limit);
        if (!rows.length) return 'No entries recorded.';
        return truncateDiscord(rows.map(entry => `• **${escapeDiscordMarkdown(entry.label)}** — ${prefix}${entry.total.toLocaleString('en-GB')} Credits · ${entry.count.toLocaleString('en-GB')} entr${entry.count === 1 ? 'y' : 'ies'}`).join('\n'));
    }

    function buildDiscordTopPayouts(report, limit = 5) {
        if (!report.topPayouts.length) return 'No positive payouts recorded.';
        return truncateDiscord(report.topPayouts.slice(0, limit).map((entry, index) => `${index + 1}. **${escapeDiscordMarkdown(entry.description)}** — +${entry.amount.toLocaleString('en-GB')} Credits`).join('\n'));
    }

    function buildDiscordComparisonField(report) {
        if (!report.comparison || !report.previous) return 'Comparison disabled.';
        return [
            `Income: **${formatPercentageChange(report.comparison.incomeChange)}**`,
            `Operating result: **${formatPercentageChange(report.comparison.operatingResultChange)}**`,
            `Capital deployed: **${formatPercentageChange(report.comparison.capitalInvestmentChange)}**`,
            `Active-hour velocity: **${formatPercentageChange(report.comparison.activeVelocityChange)}**`,
            `Mission count: **${report.comparison.missionChange > 0 ? '+' : ''}${report.comparison.missionChange.toLocaleString('en-GB')}**`,
            `Average mission reward: **${formatPercentageChange(report.comparison.averageRewardChange)}**`
        ].join('\n');
    }

    function buildDiscordScorecardField(report) {
        const score = report.scorecard;
        return [
            `Overall: **${score.grade} · ${score.overall}/100** — ${score.label}`,
            `Revenue **${score.revenue}** · Efficiency **${score.efficiency}**`,
            `Liquidity **${score.liquidity}** · Growth **${score.growth}**`,
            `Audit confidence **${score.confidence}**${score.runwayDays === null ? '' : ` · Runway **${score.runwayDays.toLocaleString('en-GB')}d**`}`
        ].join('\n');
    }

    function buildDiscordRiskField(report) {
        if (!report.riskAlerts?.length) return 'Risk analysis disabled.';
        return truncateDiscord(report.riskAlerts.map(alert => {
            const symbol = alert.severity === 'high' ? '🔴' : alert.severity === 'medium' ? '🟠' : alert.severity === 'low' ? '🟡' : '🟢';
            return `${symbol} **${escapeDiscordMarkdown(alert.title)}** — ${escapeDiscordMarkdown(alert.detail)}`;
        }).join('\n'), 1000);
    }

    function buildDiscordForecastField(report) {
        const forecast = report.forecast;
        if (!forecast) return 'Forecasting disabled.';
        return [
            forecast.endOfDayIncome === null ? '' : `Projected end-of-day income: **${formatPlainCredits(forecast.endOfDayIncome)}**`,
            `7-day income pace: **${formatPlainCredits(forecast.sevenDayIncome)}**`,
            `30-day income pace: **${formatPlainCredits(forecast.thirtyDayIncome)}**`,
            forecast.recoveryDays === null ? 'Capital recovery: **No positive operating pace available**' : `Capital recovery: **${forecast.recoveryDays.toLocaleString('en-GB')} days**`,
            forecast.projectedSevenDayBalance === null ? '' : `Projected 7-day reserve: **${formatPlainCredits(forecast.projectedSevenDayBalance)}**`,
            `Confidence: **${forecast.confidence}** · basis **${Number(forecast.basisDays || 1).toLocaleString('en-GB')} day${Number(forecast.basisDays || 1) === 1 ? '' : 's'}**`
        ].filter(Boolean).join('\n');
    }


    function buildDiscordDataQualityField(report) {
        const coverage = report.archiveComplete ? 'Complete accessible archive' : report.archiveTruncated ? 'Local archive capped' : report.ledgerComplete ? 'Full requested-period coverage' : 'Partial requested-period coverage';
        return [
            `Ledger source: **${escapeDiscordMarkdown(report.ledgerSource || 'MissionChief ledger')}**`,
            `Archive history: **${Number(report.vaultTransactionCount || 0).toLocaleString('en-GB')} transactions** · **${coverage}**`,
            `MissionChief pages: **${Number(report.ledgerPages || 0).toLocaleString('en-GB')} read / ${Number(report.ledgerLastPage || 0).toLocaleString('en-GB')} available**`,
            `Classification confidence: **${report.classificationConfidence.toLocaleString('en-GB')}%** · rules **${escapeDiscordMarkdown(activeFinancialRuleVersion)}** · policy **${escapeDiscordMarkdown(activeFinancialPolicyVersion)}**`,
            `Unclassified: **${report.unclassifiedCount.toLocaleString('en-GB')}** · ${formatPlainCredits(report.unclassifiedAmount)}`,
            `Overview checkpoint: **${escapeDiscordMarkdown(report.overviewLabel || 'Unavailable')}**`,
            report.overviewRowsUsed ? `Overview vs ledger: income **${formatSignedCredits(report.overviewIncomeVariance)}** · spending **${formatSignedCredits(report.overviewSpendingVariance)}** · net **${formatSignedCredits(report.overviewNetVariance)}**` : 'Overview vs ledger: **No complete daily checkpoint used**',
            `Balance audit: **${escapeDiscordMarkdown(report.reconciliationLabel)}**`,
            `${report.ledgerStable ? 'Ledger head remained stable' : 'New activity arrived during scanning; the local archive was left safely resumable'}${report.ledgerScanRetries ? ` · ${report.ledgerScanRetries} restart` : ''}${report.invalidTimestampCount ? ` · ${report.invalidTimestampCount} invalid timestamp rows` : ''}${report.overviewMalformedRows ? ` · ${report.overviewMalformedRows} malformed overview row${report.overviewMalformedRows === 1 ? '' : 's'}` : ''}${report.overviewDuplicateDates ? ` · ${report.overviewDuplicateDates} duplicate overview date${report.overviewDuplicateDates === 1 ? '' : 's'}` : ''}${report.ledgerScanLimitReached ? ' · page safety cap reached' : ''}${report.ledgerScanCancelled ? ' · scan stopped by user' : ''}`
        ].join('\n');
    }

    function discordEmbedCharacterCount(embed) {
        let total = String(embed?.title || '').length + String(embed?.description || '').length + String(embed?.footer?.text || '').length + String(embed?.author?.name || '').length;
        for (const field of embed?.fields || []) total += String(field.name || '').length + String(field.value || '').length;
        return total;
    }

    function fitDiscordEmbedsToBudget(embeds, maximum = 5900) {
        const result = embeds.map(embed => ({ ...embed, fields: (embed.fields || []).map(field => ({ ...field })) }));
        const count = () => result.reduce((sum, embed) => sum + discordEmbedCharacterCount(embed), 0);
        const optionalNames = ['🏆 Highest Payouts', '📊 Previous Period', '🔭 Forecast', '🗄️ Archive Coverage'];
        while (count() > maximum && optionalNames.length) {
            const name = optionalNames.shift();
            for (const embed of result) {
                const index = embed.fields.findIndex(field => field.name === name);
                if (index >= 0) { embed.fields.splice(index, 1); break; }
            }
        }
        for (const embed of result) {
            embed.description = truncateDiscord(embed.description || '', 3800);
            embed.fields = embed.fields.slice(0, 25).map(field => ({ ...field, name: truncateDiscord(field.name, 256), value: truncateDiscord(field.value, 1000) }));
        }
        return result;
    }

    function buildDiscordFinancialPayload(report, { withAttachment = false } = {}) {
        const operatingTone = reportTone(report.operatingResult);
        const colour = operatingTone === 'positive' ? 0x2ecc71 : operatingTone === 'negative' ? 0xe74c3c : 0xf1c40f;
        const topLimit = state.discordReport.topCategories;
        const condition = report.operatingResult > 0 ? 'POSITIVE OPERATING RESULT' : report.operatingResult < 0 ? 'NEGATIVE OPERATING RESULT' : 'OPERATING BREAK EVEN';
        const description = [
            `**${escapeDiscordMarkdown(report.period.label)}**`,
            escapeDiscordMarkdown(report.period.rangeLabel),
            `${condition} · **${formatSignedCredits(report.operatingResult)}**`,
            `Net credit movement after investment: **${formatSignedCredits(report.net)}**`,
            `Daily aggregate audit: **${escapeDiscordMarkdown(report.overviewLabel || 'Detailed ledger only')}**`,
            report.userName ? `Account: **${escapeDiscordMarkdown(report.userName)}**${report.userId ? ` · ID ${escapeDiscordMarkdown(report.userId)}` : ''}` : '',
            report.period.note ? `_${escapeDiscordMarkdown(report.period.note)}_` : ''
        ].filter(Boolean).join('\n');
        const balanceLines = report.openingBalance === null || report.closingBalance === null
            ? ['Balance data was unavailable.']
            : [
                `Opening: **${report.openingBalance.toLocaleString('en-GB')} Credits**`,
                `Closing: **${report.closingBalance.toLocaleString('en-GB')} Credits**`,
                `Peak: **${report.drawdown.peakBalance === null ? 'Unavailable' : report.drawdown.peakBalance.toLocaleString('en-GB')}**`,
                `Largest drawdown: **${report.drawdown.largestDrawdown === null ? 'Unavailable' : formatPlainCredits(report.drawdown.largestDrawdown)}${report.drawdown.largestDrawdownPercent === null ? '' : ` · ${report.drawdown.largestDrawdownPercent.toLocaleString('en-GB')}%`}**`
            ];
        const productivity = [
            `Missions/transport rewards: **${report.missionCount.toLocaleString('en-GB')}**`,
            `Active time estimate: **${report.activeHours.toLocaleString('en-GB')}h**`,
            `Active-hour income: **${formatPlainCredits(report.activeIncomePerHour)}**`,
            `Calendar-hour income: **${formatPlainCredits(report.incomePerHour)}**`,
            `Average / median mission: **${formatPlainCredits(report.averageMissionReward)} / ${formatPlainCredits(report.medianMissionReward)}**`,
            `Alliance / personal share: **${report.allianceIncomePercent.toLocaleString('en-GB')}% / ${report.personalIncomePercent.toLocaleString('en-GB')}%**`
        ].join('\n');
        const executive = {
            title: '📈 MissionChief Financial Command — Executive Audit',
            description: truncateDiscord(description, 4096),
            color: colour,
            timestamp: new Date(report.generatedAt).toISOString(),
            fields: [
                { name: '💰 Total Income', value: `**${formatPlainCredits(report.income)}**`, inline: true },
                { name: '🧾 Operating Costs', value: `**${formatPlainCredits(report.operatingExpense)}**`, inline: true },
                { name: '🏗️ Capital Deployed', value: `**${formatPlainCredits(report.capitalInvestment)}**`, inline: true },
                { name: report.operatingResult >= 0 ? '📊 Operating Result' : '📉 Operating Result', value: `**${formatSignedCredits(report.operatingResult)}**`, inline: true },
                { name: report.net >= 0 ? '🏦 Net Credit Movement' : '🚨 Net Credit Movement', value: `**${formatSignedCredits(report.net)}**`, inline: true },
                { name: '🎯 Operating Margin', value: `**${report.operatingMarginPercent.toLocaleString('en-GB')}%**`, inline: true },
                { name: '🏦 Liquidity & Drawdown', value: truncateDiscord(balanceLines.join('\n')), inline: true },
                { name: '⚡ Productivity', value: truncateDiscord(productivity), inline: true },
                { name: '🏅 Financial Scorecard', value: truncateDiscord(buildDiscordScorecardField(report)), inline: true },
                { name: '🚨 Intelligence Alerts', value: buildDiscordRiskField(report), inline: false },
                { name: '📊 Previous Period', value: truncateDiscord(buildDiscordComparisonField(report)), inline: false }
            ],
            footer: { text: `${SCRIPT.name} • v${SCRIPT.version} • GitHub Intelligence ${activeFinancialRuleVersion} / ${activeFinancialPolicyVersion}` }
        };
        if (withAttachment) executive.image = { url: `attachment://${FINANCE_CHART_FILENAME}` };
        const audit = {
            title: '🧠 Audit Intelligence & Capital Strategy',
            color: 0x3498db,
            fields: [
                { name: '🟢 Income Classification', value: buildDiscordCategoryBreakdown(report.incomeCategories, '+', topLimit), inline: false },
                { name: '🧾 Operating Expenditure', value: buildDiscordCategoryBreakdown(report.operatingExpenseCategories, '-', topLimit), inline: true },
                { name: '🏗️ Capital Deployment', value: buildDiscordCategoryBreakdown(report.capitalCategories, '-', topLimit), inline: true },
                { name: '🏆 Highest Payouts', value: buildDiscordTopPayouts(report, Math.min(5, topLimit)), inline: false },
                { name: '🔭 Forecast', value: truncateDiscord(buildDiscordForecastField(report)), inline: true },
                { name: '🗄️ Archive Coverage', value: truncateDiscord(buildDiscordDataQualityField(report)), inline: false }
            ],
            footer: { text: 'Operating performance is separated from capital investment. Forecasts are indicative, not guaranteed.' }
        };
        const embeds = fitDiscordEmbedsToBudget(state.discordReport.reportMode === 'executive' ? [executive] : [executive, audit]);
        const payload = {
            username: state.discordReport.webhookName || 'MissionChief Finance',
            allowed_mentions: { parse: [] },
            embeds
        };
        if (withAttachment) payload.attachments = [{ id: 0, filename: FINANCE_CHART_FILENAME, description: `${report.period.label} MissionChief financial command chart` }];
        return payload;
    }
    function roundRectPath(context, x, y, width, height, radius) {
        const r = Math.max(0, Math.min(radius, width / 2, height / 2));
        context.beginPath();
        context.moveTo(x + r, y);
        context.arcTo(x + width, y, x + width, y + height, r);
        context.arcTo(x + width, y + height, x, y + height, r);
        context.arcTo(x, y + height, x, y, r);
        context.arcTo(x, y, x + width, y, r);
        context.closePath();
    }

    function drawFinancialMetricCard(context, x, y, width, height, label, value, accent) {
        roundRectPath(context, x, y, width, height, 18);
        context.fillStyle = 'rgba(255,255,255,0.055)';
        context.fill();
        context.fillStyle = accent;
        context.fillRect(x, y, 5, height);
        context.fillStyle = 'rgba(255,255,255,0.58)';
        context.font = '700 18px Arial, sans-serif';
        context.fillText(label.toUpperCase(), x + 24, y + 31);
        context.fillStyle = '#ffffff';
        context.font = '900 34px Arial, sans-serif';
        context.fillText(value, x + 24, y + 75);
    }

    function fitFinancialCanvasText(context, value, maxWidth, { weight = 600, size = 15, minSize = 11 } = {}) {
        const sourceText = String(value ?? '');
        const widthLimit = Math.max(1, Number(maxWidth) || 1);
        let fontSize = Math.max(minSize, Number(size) || 15);
        const applyFont = () => {
            context.font = `${weight} ${fontSize}px Arial, sans-serif`;
        };
        applyFont();
        while (fontSize > minSize && context.measureText(sourceText).width > widthLimit) {
            fontSize -= 1;
            applyFont();
        }
        let renderedText = sourceText;
        let measuredWidth = context.measureText(renderedText).width;
        if (measuredWidth > widthLimit) {
            let remaining = sourceText;
            while (remaining.length > 1) {
                remaining = remaining.slice(0, -1);
                const candidate = `${remaining}…`;
                const candidateWidth = context.measureText(candidate).width;
                if (candidateWidth <= widthLimit) {
                    renderedText = candidate;
                    measuredWidth = candidateWidth;
                    break;
                }
            }
            if (measuredWidth > widthLimit) {
                renderedText = '…';
                measuredWidth = context.measureText(renderedText).width;
            }
        }
        return { text: renderedText, width: Math.min(measuredWidth, widthLimit), fontSize };
    }

    function financialSnapshotRows(report) {
        const rawDifference = report?.reconciliationDifference;
        const hasDifference = rawDifference !== null && rawDifference !== undefined && Number.isFinite(Number(rawDifference));
        let auditRow;
        if (hasDifference) {
            const difference = Number(rawDifference);
            auditRow = Math.abs(difference) <= 1
                ? ['Checkpoint audit', 'Reconciled']
                : ['Checkpoint variance', formatSignedCompactCredits(difference)];
        } else {
            auditRow = report?.overviewRowsUsed
                ? [report.overviewStatus === 'variance' ? 'Overview variance' : 'Overview audit', report.overviewStatus === 'variance' ? formatSignedCompactCredits(report.overviewNetVariance) : 'Reconciled']
                : ['Audit basis', report?.balanceCalculated ? 'Reconstructed' : 'Unavailable'];
        }
        return [
            ['Operating result', formatSignedCompactCredits(report.operatingResult)],
            ['Capital deployed', formatSignedCompactCredits(-Math.abs(report.capitalInvestment || 0))],
            ['Active-hour income', formatSignedCompactCredits(report.activeIncomePerHour || report.incomePerHour)],
            ['Classification', `${Number(report.classificationConfidence || 0).toLocaleString('en-GB', { maximumFractionDigits: 1 })}%`],
            ['Condition score', `${Number(report.scorecard?.overall || 0).toLocaleString('en-GB', { maximumFractionDigits: 0 })}/100`],
            auditRow
        ];
    }

    function drawFinancialSnapshotRow(context, x, y, width, label, value) {
        const gap = 14;
        const valueMaxWidth = Math.min(142, Math.max(96, width * 0.48));
        const valueLayout = fitFinancialCanvasText(context, value, valueMaxWidth, { weight: 800, size: 15, minSize: 11 });
        const valueRight = x + width;
        const valueLeft = valueRight - valueLayout.width;
        const labelMaxWidth = Math.max(56, valueLeft - gap - x);
        const labelLayout = fitFinancialCanvasText(context, label, labelMaxWidth, { weight: 600, size: 15, minSize: 11 });
        context.fillStyle = 'rgba(255,255,255,0.58)';
        context.textAlign = 'left';
        context.font = `600 ${labelLayout.fontSize}px Arial, sans-serif`;
        context.fillText(labelLayout.text, x, y);
        context.fillStyle = '#ffffff';
        context.textAlign = 'right';
        context.font = `800 ${valueLayout.fontSize}px Arial, sans-serif`;
        context.fillText(valueLayout.text, valueRight, y);
        context.textAlign = 'left';
        return {
            gap,
            label: { text: labelLayout.text, left: x, right: x + labelLayout.width, width: labelLayout.width, fontSize: labelLayout.fontSize },
            value: { text: valueLayout.text, left: valueLeft, right: valueRight, width: valueLayout.width, fontSize: valueLayout.fontSize }
        };
    }

    async function buildFinancialChartBlob(report) {
        try {
            const canvas = document.createElement('canvas');
            canvas.width = 1200;
            canvas.height = 675;
            const context = canvas.getContext('2d');
            if (!context) return null;
            const gradient = context.createLinearGradient(0, 0, 1200, 675);
            gradient.addColorStop(0, '#0b1018');
            gradient.addColorStop(0.55, '#111a27');
            gradient.addColorStop(1, '#080b11');
            context.fillStyle = gradient;
            context.fillRect(0, 0, 1200, 675);
            context.fillStyle = 'rgba(88,166,255,0.12)';
            context.beginPath();
            context.arc(1060, 70, 230, 0, Math.PI * 2);
            context.fill();
            context.fillStyle = 'rgba(124,77,255,0.08)';
            context.beginPath();
            context.arc(140, 650, 280, 0, Math.PI * 2);
            context.fill();
            context.fillStyle = '#ffffff';
            context.font = '900 34px Arial, sans-serif';
            context.fillText('MISSIONCHIEF FINANCIAL INTELLIGENCE', 54, 58);
            context.fillStyle = 'rgba(255,255,255,0.62)';
            context.font = '600 18px Arial, sans-serif';
            context.fillText(report.period.label, 54, 89);
            context.fillText(report.period.rangeLabel, 54, 116);
            roundRectPath(context, 1002, 38, 142, 70, 20);
            context.fillStyle = report.net >= 0 ? 'rgba(46,204,113,0.18)' : 'rgba(231,76,60,0.18)';
            context.fill();
            context.fillStyle = report.net >= 0 ? '#67e69b' : '#ff8378';
            context.font = '900 30px Arial, sans-serif';
            context.textAlign = 'center';
            context.fillText(report.grade.grade, 1073, 73);
            context.font = '700 14px Arial, sans-serif';
            context.fillText(`${report.grade.score}/100`, 1073, 96);
            context.textAlign = 'left';
            drawFinancialMetricCard(context, 54, 148, 337, 98, 'Income', formatSignedCompactCredits(report.income), '#2ecc71');
            drawFinancialMetricCard(context, 412, 148, 337, 98, 'Net movement', formatSignedCompactCredits(report.net), report.net >= 0 ? '#58a6ff' : '#ff6b61');
            drawFinancialMetricCard(context, 770, 148, 374, 98, 'Capital deployed', formatSignedCompactCredits(-Math.abs(report.capitalInvestment || 0)), '#f1c40f');
            const chartX = 54;
            const chartY = 288;
            const chartW = 730;
            const chartH = 250;
            roundRectPath(context, chartX, chartY, chartW, chartH, 18);
            context.fillStyle = 'rgba(255,255,255,0.04)';
            context.fill();
            context.fillStyle = '#ffffff';
            context.font = '800 19px Arial, sans-serif';
            context.fillText('CREDIT MOVEMENT TREND', chartX + 22, chartY + 32);
            const buckets = report.buckets.slice(-12);
            const maxMagnitude = Math.max(1, ...buckets.map(bucket => Math.abs(bucket.net)));
            const plotTop = chartY + 58;
            const plotBottom = chartY + chartH - 38;
            const zeroY = plotTop + (plotBottom - plotTop) / 2;
            context.strokeStyle = 'rgba(255,255,255,0.14)';
            context.lineWidth = 1;
            context.beginPath();
            context.moveTo(chartX + 22, zeroY);
            context.lineTo(chartX + chartW - 22, zeroY);
            context.stroke();
            const slotW = (chartW - 52) / Math.max(1, buckets.length);
            buckets.forEach((bucket, index) => {
                const height = Math.max(2, Math.abs(bucket.net) / maxMagnitude * ((plotBottom - plotTop) / 2 - 8));
                const x = chartX + 29 + index * slotW;
                const y = bucket.net >= 0 ? zeroY - height : zeroY;
                roundRectPath(context, x, y, Math.max(8, slotW - 10), height, 4);
                context.fillStyle = bucket.net >= 0 ? '#2ecc71' : '#e74c3c';
                context.fill();
                context.fillStyle = 'rgba(255,255,255,0.52)';
                context.font = '600 11px Arial, sans-serif';
                context.textAlign = 'center';
                context.fillText(bucket.label, x + Math.max(8, slotW - 10) / 2, chartY + chartH - 15);
            });
            context.textAlign = 'left';
            const detailX = 810;
            const detailY = 288;
            const detailW = 334;
            const detailH = 250;
            roundRectPath(context, detailX, detailY, detailW, detailH, 18);
            context.fillStyle = 'rgba(255,255,255,0.04)';
            context.fill();
            context.fillStyle = '#ffffff';
            context.font = '800 19px Arial, sans-serif';
            context.fillText('OPERATING SNAPSHOT', detailX + 22, detailY + 32);
            const lines = financialSnapshotRows(report);
            lines.forEach((line, index) => {
                const y = detailY + 65 + index * 29;
                drawFinancialSnapshotRow(context, detailX + 22, y, detailW - 44, line[0], line[1]);
            });
            context.fillStyle = 'rgba(255,255,255,0.42)';
            context.font = '600 14px Arial, sans-serif';
            context.fillText(`${report.activityCount.toLocaleString('en-GB')} transactions · ${report.ledgerPages.toLocaleString('en-GB')} ledger pages · ${report.overviewRowsUsed ? `${report.overviewRowsUsed.toLocaleString('en-GB')} overview day${report.overviewRowsUsed === 1 ? '' : 's'}` : 'overview unavailable'} · Generated ${new Date(report.generatedAt).toLocaleString('en-GB')}`, 54, 620);
            context.fillStyle = 'rgba(255,255,255,0.27)';
            context.font = '600 12px Arial, sans-serif';
            context.fillText(`${SCRIPT.name} v${SCRIPT.version} · Deterministic local financial audit · projections are estimates`, 54, 648);
            return await new Promise(resolve => {
                canvas.toBlob(resolve, 'image/png', 0.92);
            });
        } catch (err) {
            return null;
        }
    }

    function discordRetryDelayMs(response, attempt = 0) {
        const headerText = String(response?.responseHeaders || '');
        const retryHeader = headerText.match(/^retry-after:\s*([\d.]+)/imu);
        if (retryHeader) {
            const value = Number(retryHeader[1]);
            if (Number.isFinite(value)) return Math.max(250, value > 1000 ? value : value * 1000);
        }
        try {
            const body = JSON.parse(response?.responseText || '{}');
            const retryAfter = Number(body?.retry_after);
            if (Number.isFinite(retryAfter)) return Math.max(250, retryAfter > 1000 ? retryAfter : retryAfter * 1000);
        } catch (err) {}
        return Math.min(10000, 750 * Math.pow(2, attempt));
    }

    async function sendDiscordWithRetry(factory, maximumAttempts = 3) {
        let response = null;
        for (let attempt = 0; attempt < maximumAttempts; attempt++) {
            response = await factory();
            if (response.status !== 429 && response.status < 500) return response;
            if (attempt >= maximumAttempts - 1) return response;
            const delayMs = discordRetryDelayMs(response, attempt);
            setDiscordStatus(`Discord delivery delayed by rate limits. Retrying in ${Math.ceil(delayMs / 1000)}s…`, 'busy');
            if (!await runtimeDelay(delayMs)) throw new Error('Toolkit runtime stopped during Discord retry.');
        }
        return response;
    }

    async function sendDiscordFinancialPayload(webhookUrl, report) {
        const hasChart = Boolean(report.chartBlob && state.discordReport.includeChart);
        const payload = buildDiscordFinancialPayload(report, { withAttachment: hasChart });
        let response;
        if (hasChart) {
            response = await sendDiscordWithRetry(() => {
                const formData = new FormData();
                formData.append('payload_json', JSON.stringify(payload));
                formData.append('files[0]', report.chartBlob, FINANCE_CHART_FILENAME);
                return discordHttpRequest({
                    method: 'POST',
                    url: discordWebhookEndpoint(webhookUrl, { wait: true }),
                    data: formData
                });
            });
            if (response.status === 400 || response.status === 413 || response.status === 415) {
                const errorText = String(response.responseText || '').toLowerCase();
                const attachmentRelated = response.status === 413 || response.status === 415 || /attachment|file|upload|multipart|request entity too large/iu.test(errorText);
                if (attachmentRelated) {
                    const fallbackPayload = buildDiscordFinancialPayload(report, { withAttachment: false });
                    response = await sendDiscordWithRetry(() => discordHttpRequest({
                        method: 'POST',
                        url: discordWebhookEndpoint(webhookUrl, { wait: true }),
                        headers: { 'Content-Type': 'application/json' },
                        data: JSON.stringify(fallbackPayload)
                    }));
                }
            }
        } else {
            response = await sendDiscordWithRetry(() => discordHttpRequest({
                method: 'POST',
                url: discordWebhookEndpoint(webhookUrl, { wait: true }),
                headers: { 'Content-Type': 'application/json' },
                data: JSON.stringify(payload)
            }));
        }
        if (response.status < 200 || response.status >= 300) throw new Error(parseDiscordError(response));
        return response;
    }
