    function startPanelDrag(event) {
        if (isTouchLayoutActive()) return;
        const isMouse = event.type === 'mousedown';
        const isTouch = event.type === 'touchstart';
        if (isMouse && event.button !== 0) return;
        if (!isMouse && !isTouch) return;
        const panel = document.getElementById(SCRIPT.panelId);
        if (!panel || !panel.classList.contains('mcms-open')) return;
        const point = isTouch ? event.touches[0] : event;
        if (!point) return;
        const rect = panel.getBoundingClientRect();
        dragState = {
            startX: point.clientX,
            startY: point.clientY,
            startLeft: rect.left,
            startTop: rect.top,
            moved: false
        };
        panel.classList.add('mcms-dragging');
        document.documentElement.style.cursor = 'grabbing';
        document.body.style.userSelect = 'none';
        document.addEventListener('mousemove', movePanelDrag, true);
        document.addEventListener('mouseup', endPanelDrag, true);
        document.addEventListener('touchmove', movePanelDrag, { capture: true, passive: false });
        document.addEventListener('touchend', endPanelDrag, true);
        document.addEventListener('touchcancel', endPanelDrag, true);
        event.preventDefault();
        event.stopPropagation();
    }

    function movePanelDrag(event) {
        if (!dragState) return;
        const isTouch = event.type === 'touchmove';
        const point = isTouch ? event.touches[0] : event;
        if (!point) return;
        const dx = point.clientX - dragState.startX;
        const dy = point.clientY - dragState.startY;
        if (Math.abs(dx) > 2 || Math.abs(dy) > 2) dragState.moved = true;
        const pos = clampPanelPosition(dragState.startLeft + dx, dragState.startTop + dy);
        setPanelCssPosition(pos.left, pos.top);
        event.preventDefault();
        event.stopPropagation();
    }

    function endPanelDrag(event) {
        if (!dragState) return;
        const didMove = Boolean(dragState.moved);
        const panel = document.getElementById(SCRIPT.panelId);
        if (panel) {
            panel.classList.remove('mcms-dragging');
            const rect = panel.getBoundingClientRect();
            const pos = clampPanelPosition(rect.left, rect.top);
            setPanelCssPosition(pos.left, pos.top);
            state.panelPosition = { left: pos.left, top: pos.top };
            saveState();
        }
        dragState = null;
        document.documentElement.style.cursor = '';
        document.body.style.userSelect = '';
        document.removeEventListener('mousemove', movePanelDrag, true);
        document.removeEventListener('mouseup', endPanelDrag, true);
        document.removeEventListener('touchmove', movePanelDrag, true);
        document.removeEventListener('touchend', endPanelDrag, true);
        document.removeEventListener('touchcancel', endPanelDrag, true);
        if (didMove) {
            suppressNextOutsideClick = true;
            showToast('Menu position saved');
            runtimeSetTimeout(() => { suppressNextOutsideClick = false; }, 250);
        }
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
    }

    function openPanel() {
        const panel = document.getElementById(SCRIPT.panelId) || createPanel();
        if (!panel) return;
        applyRootAttributes();
        refreshTabletModeUi(panel);
        panel.classList.add('mcms-open');
        panel.setAttribute('aria-hidden', 'false');
        const menuButton = document.querySelector(`#${SCRIPT.controlId} .mcms-menu-btn`);
        menuButton?.setAttribute('aria-expanded', 'true');
        fitControlToMap();
        runtimeSetTimeout(() => positionPanelOverlay(true), 0);
    }

    function closePanel({ restoreFocus = false } = {}) {
        const panel = document.getElementById(SCRIPT.panelId);
        if (!panel) return;
        panel.classList.remove('mcms-open');
        panel.setAttribute('aria-hidden', 'true');
        const menuButton = document.querySelector(`#${SCRIPT.controlId} .mcms-menu-btn`);
        menuButton?.setAttribute('aria-expanded', 'false');
        if (restoreFocus && menuButton?.isConnected) runtimeSetTimeout(() => menuButton.focus({ preventScroll: true }), 0);
    }

    function togglePanel() {
        const panel = document.getElementById(SCRIPT.panelId);
        if (!panel) { openPanel(); return; }
        panel.classList.contains('mcms-open') ? closePanel() : openPanel();
    }

    function closeHelpCenter({ restoreFocus = true } = {}) {
        const overlay = document.getElementById(SCRIPT.helpCenterId);
        if (!overlay?.classList.contains('mcms-open')) return false;
        overlay.classList.remove('mcms-open', 'mcms-loading', 'mcms-error');
        overlay.setAttribute('aria-hidden', 'true');
        document.documentElement.removeAttribute('data-mcms-help-open');
        if (restoreFocus && helpCenterReturnFocus?.isConnected) {
            runtimeSetTimeout(() => { try { helpCenterReturnFocus.focus({ preventScroll: true }); } catch (err) {} }, 0);
        }
        helpCenterReturnFocus = null;
        return true;
    }

    function helpGuideRequestUrl(force = false) {
        const separator = HELP_CENTER.rawUrl.includes('?') ? '&' : '?';
        const cacheKey = force ? `${SCRIPT.version}-${Date.now()}` : SCRIPT.version;
        return `${HELP_CENTER.rawUrl}${separator}toolkit=${encodeURIComponent(cacheKey)}`;
    }

    function requestHelpGuideDocument(force = false) {
        if (!force && helpGuideDocumentCache) return Promise.resolve(helpGuideDocumentCache);
        if (helpGuideLoadPromise) return helpGuideLoadPromise;
        const url = helpGuideRequestUrl(force);
        helpGuideLoadPromise = new Promise((resolve, reject) => {
            if (runtime.destroyed) {
                reject(new Error('Toolkit runtime stopped.'));
                return;
            }
            const validate = text => {
                const documentText = String(text || '').trim();
                if (!/<!doctype html|<html[\s>]/iu.test(documentText) || !documentText.includes('MissionChief Map Command Toolkit')) {
                    throw new Error('The Help Centre returned an invalid document.');
                }
                helpGuideDocumentCache = documentText;
                helpGuideLoadedAt = Date.now();
                return documentText;
            };
            if (typeof GM_xmlhttpRequest === 'function') {
                let request = null;
                let settled = false;
                const finish = (error, response = null) => {
                    if (settled) return;
                    settled = true;
                    if (request) runtime.requests.delete(request);
                    try {
                        if (error) throw error;
                        if (!response || Number(response.status) < 200 || Number(response.status) >= 300) throw new Error(`Help Centre returned HTTP ${response?.status || 'error'}.`);
                        resolve(validate(response.responseText));
                    } catch (err) {
                        reject(err instanceof Error ? err : new Error('The Help Centre could not be loaded.'));
                    }
                };
                try {
                    request = GM_xmlhttpRequest({
                        method: 'GET', url, timeout: HELP_CENTER.requestTimeoutMs, responseType: 'text',
                        headers: { Accept: 'text/html, text/plain;q=0.9, */*;q=0.8' },
                        onload: response => finish(null, response),
                        onerror: () => finish(new Error('GitHub could not be reached.')),
                        ontimeout: () => finish(new Error('The Help Centre request timed out.')),
                        onabort: () => finish(new Error('The Help Centre request was cancelled.'))
                    });
                    if (!settled && request?.abort) runtime.requests.add(request);
                } catch (err) {
                    finish(err instanceof Error ? err : new Error('The Help Centre request could not be created.'));
                }
                return;
            }
            runtimeFetch(url, { cache: force ? 'reload' : 'default', credentials: 'omit' })
                .then(response => {
                    if (!response.ok) throw new Error(`Help Centre returned HTTP ${response.status}.`);
                    return response.text();
                })
                .then(text => resolve(validate(text)))
                .catch(error => reject(error instanceof Error ? error : new Error('GitHub could not be reached.')));
        }).finally(() => { helpGuideLoadPromise = null; });
        return helpGuideLoadPromise;
    }

    function patchHelpGuideDocument(documentText) {
        let source = String(documentText || '');
        source = source
            .replace(/Guide for Toolkit v\d+\.\d+\.\d+/u, `Guide for Toolkit v${HELP_CENTER.guideVersion}`)
            .replace(/Help Centre for v\d+\.\d+\.\d+/u, `Help Centre for v${HELP_CENTER.guideVersion}`)
            .replace(
                '<div class="card"><h3>Umbrella</h3><p>Sterile biohazard command styling with classified containment panels.</p></div>',
                '<div class="card"><h3>Umbrella Containment</h3><p>Corporate BSL-4 command styling with original transparent emblem, facility schematic, surveillance terminal, specimen vial and containment-division artwork.</p></div>'
            )
            .replace('Biohazard Containment</span>', 'Umbrella Containment</span>')
            .replace(
                'Set a minimum payout threshold, duration, theme, audio state and volume. Use the test amount control before relying on a new setup.',
                'Set a minimum payout threshold, duration, theme, audio state and volume. Umbrella Containment uses the same identity, artwork package and renamed hosted audio as the Umbrella UI theme. Use the test amount control before relying on a new setup.'
            )
            .replace(
                '<li>Presentation titles and particle treatment scale by payout tier.</li>',
                '<li>Presentation titles and particle treatment scale by payout tier.</li><li>Umbrella Containment displays BSL-4 facility, surveillance, corporate emblem and transfer-authorisation artwork.</li>'
            );
        const semanticMarker = '<div class="callout warning"><strong>Protected semantic colours:</strong> clearing, assistance, warning, critical and syncing states retain their operational meaning across every theme.</div>';
        if (!source.includes('Umbrella Containment asset package:') && source.includes(semanticMarker)) {
            source = source.replace(
                semanticMarker,
                '<div class="callout"><strong>Umbrella Containment asset package:</strong> decorative artwork is loaded from the public Toolkit assets repository only while the theme is in use. Missing artwork never blocks the Toolkit, and the graphics do not replace protected operational colours.</div>' + semanticMarker
            );
        }
        if (!source.includes('id="financial-command"')) {
            const financialSection = `<section class="section" id="financial-command" data-title="Discord Financial Command" data-keywords="discord finance archive ledger audit github rules policy deep scan forecast risk capital investment webhook">
<div class="head"><span class="num">19</span><div><h2>Discord Financial Command</h2><p class="summary">MissionChief ledger extraction, daily `/credits/overview` reconciliation, local historical archiving and GitHub-hosted financial intelligence.</p></div></div>
<h3>Supreme financial audit</h3><p>The Discord tab can generate an Executive Brief or a complete Executive + Full Audit report. The audit separates operating income, other income, operating expenditure and capital investment so expansion spending does not automatically make healthy operations look unprofitable.</p>
<div class="grid"><div class="card"><h4>Financial scorecard</h4><p>Revenue, operating efficiency, liquidity, growth investment and audit confidence are scored independently.</p></div><div class="card"><h4>Daily aggregate audit</h4><p>MissionChief Revenue, Spendings and Sum rows verify complete days without double-counting the detailed ledger. Any unresolved variance remains visible.</p></div><div class="card"><h4>Risk intelligence</h4><p>Highlights overview variance, revenue contraction, concentration, aggressive investment, reserve drawdown, low runway and incomplete classification.</p></div><div class="card"><h4>Deep ledger scan</h4><p>All Available History reads every MissionChief credit-ledger page accessible to the account, with retries, progress reporting, safe cancellation and local checkpoint storage.</p></div><div class="card"><h4>GitHub intelligence</h4><p>Classification rules and audit thresholds are downloaded from the public Toolkit assets repository and cached locally. No player ledger or webhook data is uploaded.</p></div></div>
<h3>Player-linked Local Financial Archive</h3><ol class="steps"><li>Keep Local Financial Archive enabled to retain discovered transactions by MissionChief player ID/name.</li><li>Select All Available History or run Deep Scan All Available to extend the archive as far back as MissionChief exposes.</li><li>Use Export Archive and Import Archive to transfer or merge history between your devices without exposing repository credentials.</li><li>Export All also includes the local archive and Discord webhook for complete private recovery.</li><li>GitHub hosts only public rules, audit policy and Toolkit assets; player financial data remains in the browser and private backups.</li></ol>
<div class="call warn"><strong>Private backup:</strong> Export All includes the saved Discord webhook and local financial history. Store the JSON privately; anyone holding it may be able to post through the webhook and inspect the exported game ledger.</div>
</section>`;
            source = source.replace('</main>', `${financialSection}</main>`);
        }
        if (!source.includes('id="economy-mode"')) {
            const economySection = `<section class="section" id="economy-mode" data-title="Economy Mode" data-keywords="economy eco performance low end laptop ram cpu gpu lag leaflet markers">
<div class="head"><span class="num">20</span><div><h2>Economy Mode</h2><p class="summary">A reversible lower-overhead operating policy for large maps and lower-end computers.</p></div></div>
<p>Use the leaf button beside the Toolkit opener to switch Economy Mode on or off. Your normal themes, overlays and feature selections remain saved; Economy Mode temporarily renders and refreshes them more efficiently.</p>
<div class="grid"><div class="card"><h4>Map workload</h4><p>Off-screen vehicle and building layers are detached with a safety buffer, then restored automatically when they enter the current map area or Economy Mode is disabled.</p></div><div class="card"><h4>Rendering</h4><p>Continuous decorative animation, tile-filter chains, backdrop blur and heavy payout particles are replaced by static equivalents while operational colours remain intact.</p></div><div class="card"><h4>Background work</h4><p>Mission, vehicle, building and maintenance refreshes use longer idle intervals. Opening a module, changing a setting or pressing Refresh still requests current data immediately.</p></div><div class="card"><h4>Large panels</h4><p>Long MissionChief lists use browser rendering containment so off-screen rows do not require full layout and painting.</p></div></div>
<div class="call"><strong>Full restoration:</strong> switching Economy Mode off reattaches quarantined layers, restores Leaflet options, map skins, animation and normal scheduler intervals.</div>
</section>`;
            source = source.replace('</main>', `${economySection}</main>`);
        }
        return source;
    }

    function protectHelpGuideDocument(documentText) {
        const navigationGuard = `
<script data-mcms-help-navigation-guard>
(() => {
    'use strict';
    const scrollToGuideSection = rawHref => {
        const href = String(rawHref || '');
        if (!href.startsWith('#')) return false;
        let id = '';
        try { id = decodeURIComponent(href.slice(1)); } catch (error) { id = href.slice(1); }
        const target = id ? document.getElementById(id) : document.documentElement;
        if (!target) return true;
        const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
        return true;
    };
    document.addEventListener('click', event => {
        const link = event.target instanceof Element ? event.target.closest('a[href]') : null;
        if (!link) return;
        const href = link.getAttribute('href') || '';
        if (href.startsWith('#')) {
            event.preventDefault();
            scrollToGuideSection(href);
            return;
        }
        if (/^(?:https?:)?\/\//i.test(href)) {
            event.preventDefault();
            try { window.open(href, '_blank', 'noopener,noreferrer'); } catch (error) {}
        }
    }, true);
})();
\x3C/script>`;
        const source = patchHelpGuideDocument(documentText);
        if (source.includes('data-mcms-help-navigation-guard')) return source;
        if (/<\/body\s*>/iu.test(source)) return source.replace(/<\/body\s*>/iu, `${navigationGuard}</body>`);
        return `${source}${navigationGuard}`;
    }

    function createHelpCenter() {
        const existing = document.getElementById(SCRIPT.helpCenterId);
        if (existing) return existing;
        const overlay = document.createElement('div');
        overlay.id = SCRIPT.helpCenterId;
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');
        overlay.setAttribute('aria-label', `${SCRIPT.name} Help Centre`);
        overlay.setAttribute('aria-hidden', 'true');
        overlay.innerHTML = `
            <div class="mcms-help-window" role="document">
                <div class="mcms-help-toolbar">
                    <div class="mcms-help-brand">
                        <span class="mcms-help-brand-icon" aria-hidden="true">?</span>
                        <span class="mcms-help-brand-copy"><strong>Toolkit Help Centre</strong><small>Searchable guide · hosted on the public Toolkit assets repository</small></span>
                    </div>
                    <div class="mcms-help-actions">
                        <button class="mcms-help-action" type="button" data-help-action="reload" title="Reload the latest guide" aria-label="Reload the latest guide">↻</button>
                        <button class="mcms-help-action mcms-help-source" type="button" data-help-action="source" title="Open the guide source on GitHub" aria-label="Open the guide source on GitHub">↗</button>
                        <button class="mcms-help-action mcms-help-close" type="button" data-help-action="close" title="Close Help Centre" aria-label="Close Help Centre">×</button>
                    </div>
                </div>
                <div class="mcms-help-address"><span class="mcms-help-address-lock" aria-hidden="true">●</span><span class="mcms-help-address-text">github.com/Conroy1988/missionchief-toolkit-assets/help/index.html</span><span class="mcms-help-status" data-help-status>Ready</span></div>
                <div class="mcms-help-progress" aria-hidden="true"></div>
                <div class="mcms-help-content">
                    <iframe class="mcms-help-frame" title="MissionChief Map Command Toolkit searchable guide" sandbox="allow-scripts allow-popups" referrerpolicy="no-referrer"></iframe>
                    <div class="mcms-help-fallback">
                        <div class="mcms-help-error-card">
                            <strong>Help Centre unavailable</strong>
                            <p data-help-error>The public guide could not be loaded. The main Toolkit remains fully operational.</p>
                            <div class="mcms-help-error-actions"><button type="button" data-help-action="reload">Retry</button><button type="button" data-help-action="source">Open GitHub source</button></div>
                        </div>
                    </div>
                </div>
            </div>`;
        runtimeListen(overlay, 'click', event => {
            const actionButton = closestEventTarget(event, '[data-help-action]');
            if (actionButton) {
                event.preventDefault();
                const action = actionButton.dataset.helpAction;
                if (action === 'close') closeHelpCenter();
                if (action === 'reload') loadHelpCenterGuide(true);
                if (action === 'source') {
                    try { pageWindow.open(HELP_CENTER.sourceUrl, '_blank', 'noopener,noreferrer'); } catch (err) { location.href = HELP_CENTER.sourceUrl; }
                }
                return;
            }
            if (event.target === overlay) closeHelpCenter();
        });
        runtimeListen(overlay, 'mousedown', stopMapInteraction);
        runtimeListen(overlay, 'wheel', stopMapInteraction, { passive: true });
        runtimeListen(overlay, 'touchstart', stopMapInteraction, { passive: true });
        document.body.appendChild(overlay);
        return overlay;
    }

    async function loadHelpCenterGuide(force = false) {
        const overlay = createHelpCenter();
        const frame = overlay.querySelector('.mcms-help-frame');
        const status = overlay.querySelector('[data-help-status]');
        const errorText = overlay.querySelector('[data-help-error]');
        overlay.classList.add('mcms-loading');
        overlay.classList.remove('mcms-error');
        if (status) status.textContent = force ? 'Refreshing…' : 'Loading…';
        try {
            const documentText = await requestHelpGuideDocument(force);
            if (!overlay.isConnected || runtime.destroyed) return false;
            frame.srcdoc = protectHelpGuideDocument(documentText);
            overlay.classList.remove('mcms-error');
            if (status) status.textContent = `Guide ${HELP_CENTER.guideVersion} · online`;
            return true;
        } catch (err) {
            if (!overlay.isConnected || runtime.destroyed) return false;
            overlay.classList.add('mcms-error');
            if (status) status.textContent = 'Offline fallback';
            if (errorText) errorText.textContent = `${err?.message || 'The public guide could not be loaded.'} The main Toolkit remains fully operational.`;
            return false;
        } finally {
            overlay.classList.remove('mcms-loading');
        }
    }

    function openHelpCenter() {
        const overlay = createHelpCenter();
        helpCenterReturnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        closePanel();
        overlay.classList.add('mcms-open');
        overlay.setAttribute('aria-hidden', 'false');
        document.documentElement.setAttribute('data-mcms-help-open', 'true');
        const closeButton = overlay.querySelector('[data-help-action="close"]');
        runtimeSetTimeout(() => { try { closeButton?.focus({ preventScroll: true }); } catch (err) {} }, 0);
        const frame = overlay.querySelector('.mcms-help-frame');
        if (!frame?.srcdoc) loadHelpCenterGuide(false);
        else {
            const status = overlay.querySelector('[data-help-status]');
            if (status) status.textContent = helpGuideLoadedAt ? `Guide ${HELP_CENTER.guideVersion} · cached` : `Guide ${HELP_CENTER.guideVersion}`;
        }
    }

    function stopMapInteraction(event) {
        event.stopPropagation();
    }

    function isTypingTarget(target) {
        if (!target) return false;
        const tag = String(target.tagName || '').toLowerCase();
        return tag === 'input' || tag === 'textarea' || tag === 'select' || target.isContentEditable;
    }

    function handleKeyboard(event) {
        if (event.key === 'Escape' && closeHelpCenter()) { event.preventDefault(); return; }
        if (event.key === 'Escape') {
            const hadOpenUi = Boolean(
                document.getElementById(SCRIPT.panelId)?.classList.contains('mcms-open') ||
                document.getElementById(SCRIPT.vehicleStatusId)?.classList.contains('mcms-open')
            );
            if (state.cleanMode && state.shortcuts) toggleFeature('clean');
            closePanel({ restoreFocus: hadOpenUi });
            closeVehicleCodeStatus();
            if (hadOpenUi) event.preventDefault();
            return;
        }
        if (!state.shortcuts || isTypingTarget(event.target)) return;
        const key = String(event.key || '').toLowerCase();
        if (!event.ctrlKey && !event.altKey && !event.metaKey && key === 'm') { event.preventDefault(); togglePanel(); return; }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && !event.repeat && /^[1-9]$/.test(event.key)) {
            const visibilityShortcut = {
                '1': 'myMissions',
                '2': 'allianceMissions',
                '3': 'vehicles',
                '4': 'buildings',
                '5': 'allianceCredits',
                '6': 'missionAge',
                '7': 'transportWatcher',
                '8': 'unitCommitment',
            };
            event.preventDefault();
            toggleFeature(visibilityShortcut[event.key]);
            return;
        }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && !event.repeat && key === 'v') { event.preventDefault(); toggleVehicleCodeStatus(); return; }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && key === 'c') { event.preventDefault(); toggleFeature('clean'); return; }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && key === 'f') { event.preventDefault(); toggleFeature('markerFocus'); return; }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && key === 'p') { event.preventDefault(); toggleFeature('missionPulse'); return; }
        if (!event.ctrlKey && !event.altKey && !event.metaKey && key === 'r') { event.preventDefault(); toggleFeature('roadPriority'); }
    }

    function buildThemeOptions(selected) {
        return THEME_ORDER.map(key => `<option value="${key}" ${key === selected ? 'selected' : ''}>${THEMES[key].full}</option>`).join('');
    }

    function makeToggleButton(key, icon, label, title) {
        return `
            <button class="mcms-toggle-btn" type="button" data-toggle="${key}" title="${escapeHtml(title || label)}">
                <span class="mcms-iconbox">${icon}</span>
                <span class="mcms-text">
                    <span class="mcms-label">${escapeHtml(label)}</span>
                    <span class="mcms-pill">OFF</span>
                </span>
            </button>
        `;
    }

    function makeAllianceMemberManagerToggleButton() {
        return `
            <button class="mcms-toggle-btn" type="button" data-action="toggle-alliance-member-manager" data-mcms-alliance-member-manager-toggle="true" title="Enable or disable Alliance Member Manager" aria-label="Alliance Member Manager" aria-pressed="false">
                <span class="mcms-iconbox">AM</span>
                <span class="mcms-text">
                    <span class="mcms-label">Alliance Member Manager</span>
                    <span class="mcms-pill">OFF</span>
                </span>
            </button>
        `;
    }

    function makeFloatButton(key, shortcut, label, title, tabletLabel = label, mobileLabel = tabletLabel) {
        return `
            <button class="mcms-float-btn" type="button" data-toggle="${key}" title="${escapeHtml(title)}" aria-pressed="false">
                <span class="mcms-float-key">${escapeHtml(shortcut)}</span>
                <span class="mcms-float-label mcms-float-label-desktop">${escapeHtml(label)}</span>
                <span class="mcms-float-label mcms-float-label-tablet">${escapeHtml(tabletLabel)}</span>
                <span class="mcms-float-label mcms-float-label-mobile">${escapeHtml(mobileLabel)}</span>
            </button>
        `;
    }

    function makeActionFloatButton(action, shortcut, label, title, tabletLabel = label, mobileLabel = tabletLabel) {
        return `
            <button class="mcms-float-btn mcms-float-action-btn" type="button" data-action="${escapeHtml(action)}" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}" aria-keyshortcuts="${escapeHtml(shortcut)}" aria-pressed="false">
                <span class="mcms-float-key">${escapeHtml(shortcut)}</span>
                <span class="mcms-float-label mcms-float-label-desktop">${escapeHtml(label)}</span>
                <span class="mcms-float-label mcms-float-label-tablet">${escapeHtml(tabletLabel)}</span>
                <span class="mcms-float-label mcms-float-label-mobile">${escapeHtml(mobileLabel)}</span>
            </button>
        `;
    }

    // Issue #153: stable live Toolkit version-status control.
